(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-cybersecurity'] = AINOW['data/data-cybersecurity'] || {};
const cybersecurityPrompts = [

  {"id":"sec-1","title":"MITRE ATT&CK Threat Model for SaaS Platform","prompt":"You are a threat intelligence analyst at a 200-person B2B SaaS company processing healthcare data under HIPAA, running entirely on AWS with Okta for identity. Using the MITRE ATT&CK Enterprise framework v14, build a threat model for your customer-facing web application. Identify the five most relevant attack techniques by technique ID — for example T1566.001 Spearphishing Attachment, T1078 Valid Accounts, T1190 Exploit Public-Facing Application — that adversaries would realistically use against this architecture. For each technique, describe the specific detection opportunity using CloudTrail, GuardDuty, or Okta System Log events, and propose one preventive control aligned to CIS Controls v8. Output as a table with columns: Technique ID, Technique Name, Realistic Attack Scenario, Detection Data Source, Preventive Control.","tags":["threat-intelligence","mitre-attack","aws","hipaa","threat-modeling"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"sec-2","title":"FIN7 Adversary Emulation Plan for Purple Team","prompt":"You are a senior threat intelligence engineer at a regional bank with 1,200 employees, running on-premise Active Directory federated with Azure AD, using Palo Alto firewalls and Splunk Enterprise SIEM. Build a structured adversary emulation plan based on the FIN7 threat actor profile, referencing their documented MITRE ATT&CK techniques including T1059.001 PowerShell execution, T1055 Process Injection, and T1041 Exfiltration over C2 Channel. The plan should cover three phases: initial access via spearphishing with a malicious Office macro, lateral movement using stolen credentials and PsExec, and data staging before exfiltration. For each phase, list the specific tooling FIN7 uses (Carbanak backdoor, GRIFFON JavaScript downloader), the expected Splunk SPL detection query structure, and the recommended NIST CSF 2.0 Respond function actions. Output a structured emulation plan document suitable for a purple team exercise.","tags":["threat-intelligence","adversary-emulation","fin7","purple-team","splunk"],"author":"AINOW","created":"2024-02-15T10:05:00Z","featured":false},

  {"id":"sec-3","title":"Threat Hunting Hypotheses for Credential-Based Attacks","prompt":"You are a threat hunter at an e-commerce company processing 50,000 daily transactions, using Microsoft Sentinel as your SIEM, CrowdStrike Falcon for EDR, and Azure AD for identity. Develop five structured threat hunting hypotheses targeting credential-based attack techniques from MITRE ATT&CK tactics TA0006 Credential Access and TA0008 Lateral Movement. Each hypothesis should follow the format: Assumption (what adversary behavior you expect), Data Sources (specific Sentinel table names such as SigninLogs, SecurityEvent, DeviceProcessEvents), KQL query skeleton to surface anomalies, and the false positive tuning strategy. Focus specifically on Pass-the-Hash via T1550.002, Kerberoasting via T1558.003, and LSASS memory dumping via T1003.001, given that your environment has Windows Server 2019 domain controllers and a mix of Windows 10 and 11 endpoints.","tags":["threat-hunting","credential-attacks","microsoft-sentinel","kql","crowdstrike"],"author":"AINOW","created":"2024-02-15T10:10:00Z","featured":false},

  {"id":"sec-4","title":"STRIDE Threat Model for PCI DSS Payment API","prompt":"You are a security architect at a Series B fintech startup building a payment processing API handling Visa and Mastercard transactions, deployed on GCP Cloud Run with Firestore as the database, behind Apigee API Gateway, subject to PCI DSS v4.0. Perform a complete STRIDE threat model for the payment authorization flow: mobile app to Apigee Gateway to Cloud Run microservice to Firestore to card network. For each STRIDE category — Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service, Elevation of Privilege — identify two specific threats applicable to this architecture, assign a DREAD risk score on a 1–10 scale across Damage, Reproducibility, Exploitability, Affected Users, and Discoverability, and map each threat to the relevant PCI DSS v4.0 requirement. Output as a structured threat model table.","tags":["threat-modeling","stride","pci-dss","gcp","api-security"],"author":"AINOW","created":"2024-02-15T10:15:00Z","featured":false},

  {"id":"sec-5","title":"Software Supply Chain Threat Intelligence Assessment","prompt":"You are a threat intelligence lead at a 3,000-employee manufacturing company relying on 40 third-party software vendors, managing Windows Server 2022 and RHEL 9 systems via Ansible, with Tenable.sc for vulnerability management. Following the SolarWinds SUNBURST attack pattern and the 3CX supply chain compromise, build a supplier threat intelligence assessment framework. Cover: evaluating each vendor's SBOM against CISA's Known Exploited Vulnerabilities catalog, modeling realistic attack paths using MITRE ATT&CK technique T1195.002 Compromise Software Supply Chain, specific Tenable plugin families to monitor for supply-chain-relevant CVEs, and a vendor risk tiering model (Tier 1–3) with quarterly review cadence. Include a checklist of 10 questions to send to Tier 1 vendors based on NIST SP 800-161r1.","tags":["supply-chain","threat-intelligence","sbom","cisa-kev","vendor-risk"],"author":"AINOW","created":"2024-02-15T10:20:00Z","featured":false},

  {"id":"sec-6","title":"Dark Web Monitoring Program for Retail Company","prompt":"You are a cyber threat intelligence analyst at a publicly traded retail company with 800 stores and an e-commerce platform holding 2 million customer records, using Recorded Future and Have I Been Pwned Enterprise for external threat intelligence. Design a structured dark web monitoring program covering: the specific data types to monitor (employee credential dumps, customer PII, payment card data matching your BIN ranges, leaked source code referencing your domain), the workflow for triaging and validating discovered intelligence against your Splunk asset inventory, how to operationalize findings into CrowdStrike IOC blocking within 4 hours of discovery, and the escalation path for material breach indicators under SEC cybersecurity disclosure rules requiring Form 8-K filing. Include a sample alert template for the CISO and legal team when compromised credentials are confirmed.","tags":["threat-intelligence","dark-web","recorded-future","credential-monitoring","sec-disclosure"],"author":"AINOW","created":"2024-02-15T10:25:00Z","featured":false},

  {"id":"sec-7","title":"LockBit 3.0 Ransomware Threat Profile for Healthcare","prompt":"You are a threat intelligence specialist supporting a regional hospital network with 12 facilities running Epic EHR, Cisco network infrastructure, and medical IoT devices including infusion pumps and imaging systems that cannot be frequently patched. Produce a detailed threat profile for the LockBit 3.0 ransomware-as-a-service operation targeting healthcare, covering: their documented initial access vectors (RDP exploitation, VPN credential brute force, phishing with malicious OneNote attachments), their use of MITRE ATT&CK techniques T1486 Data Encrypted for Impact and T1489 Service Stop, the specific Windows Event IDs 4625, 4648, and 7045 and Sysmon event types that indicate pre-ransomware activity, and recommended detection rules in Splunk ES notable event format. Describe the CISA healthcare sector advisory recommendations most relevant to limiting blast radius when a single facility is compromised.","tags":["threat-intelligence","ransomware","lockbit","healthcare","critical-infrastructure"],"author":"AINOW","created":"2024-02-15T10:30:00Z","featured":true},

  {"id":"sec-8","title":"MISP Threat Intelligence Platform Integration Architecture","prompt":"You are a security architect at a 500-person financial services firm that has purchased a MISP (Malware Information Sharing Platform) instance and wants to integrate it with Splunk SIEM, Palo Alto Cortex XSOAR for SOAR, and CrowdStrike Falcon Intelligence. Design the integration architecture covering: TAXII 2.1 feed configuration to ingest ISAC feeds from FS-ISAC and CISA AIS, the STIX 2.1 object types (indicator, threat-actor, campaign, course-of-action) and how each maps to actionable Splunk lookups or CrowdStrike custom IOC lists, the XSOAR playbook logic for auto-enriching Splunk alerts with MISP context, and the governance model for indicator lifecycle management from ingestion through validation, activation, and expiry. Include the data flow diagram description and the estimated false positive reduction from indicator scoring using MISP's confidence and TLP marking scheme.","tags":["threat-intelligence","misp","stix-taxii","splunk","xsoar"],"author":"AINOW","created":"2024-02-15T10:35:00Z","featured":false},

  {"id":"sec-9","title":"APT Campaign Attribution Using the Diamond Model","prompt":"You are a senior CTI analyst supporting a defense contractor operating a classified network alongside a commercial AWS GovCloud environment, with Elastic SIEM and Carbon Black EDR deployed across both. A recent intrusion left artifacts: DLL side-loading using a signed VMware binary, RC4-encrypted C2 traffic to a domain registered in 2023 with WHOIS privacy, and Cobalt Strike with a modified Malleable C2 profile. Conduct a structured attribution analysis using the Diamond Model of Intrusion Analysis, covering adversary, capability, infrastructure, and victim characteristics. Map the observed TTPs to specific APT groups documented in the MITRE ATT&CK Groups database. Identify three corroborating data points that would increase attribution confidence from speculative to probable, and describe how to share this intelligence via STIX 2.1 with a government ISAC partner while protecting source and methods.","tags":["threat-intelligence","apt","attribution","diamond-model","cobalt-strike"],"author":"AINOW","created":"2024-02-15T10:40:00Z","featured":false},

  {"id":"sec-10","title":"Threat Model for Kubernetes Microservices Platform","prompt":"You are a principal security engineer at a Series C fintech company with 300 engineers, operating a Kubernetes-based microservices platform on AWS EKS, using Istio service mesh, Kafka for event streaming, and HashiCorp Vault for secrets management. Conduct a data-flow-based threat model for the loan origination service that accepts customer financial data, calls three downstream microservices via gRPC, writes to Aurora PostgreSQL, and publishes events to Kafka. Identify threats at each trust boundary crossing using the OWASP Threat Dragon methodology, covering: container escape via CVE-2022-0492 cgroup namespace bypass, Istio mTLS misconfiguration enabling service impersonation, Vault token over-permissioning leading to secrets sprawl, and Kafka consumer group authorization bypass. For each threat, specify the MITRE ATT&CK Cloud technique, the Kubernetes audit log query to detect it, and the remediation referencing CIS Kubernetes Benchmark v1.8 controls.","tags":["threat-modeling","kubernetes","microservices","hashicorp-vault","istio"],"author":"AINOW","created":"2024-02-15T10:45:00Z","featured":false},

  {"id":"sec-11","title":"External Penetration Test Scoping Document","prompt":"You are a senior penetration tester at a security consultancy preparing a statement of work for an authorized external network penetration test against a mid-size insurance company with 600 employees. The client runs a public-facing web portal on Azure App Service, a Fortinet FortiGate SSL VPN, a Microsoft 365 environment, and several legacy SOAP web services. Draft a complete scoping document covering: Rules of Engagement including emergency halt procedures, the specific IP ranges and domains in scope, the testing methodology referencing PTES Technical Guidelines and OWASP Testing Guide v4.2, the toolset to be used (Nmap, Nuclei, Burp Suite Pro, Metasploit Framework, BloodHound, Impacket), the deliverables including an executive summary and CVSS-scored technical findings, and data handling requirements for any credentials or PII discovered. Include a sample escalation contact matrix and the criteria for moving from passive reconnaissance to active exploitation.","tags":["penetration-testing","scoping","ptes","burp-suite","metasploit"],"author":"AINOW","created":"2024-02-15T10:50:00Z","featured":true},

  {"id":"sec-12","title":"Web Application Penetration Test Methodology","prompt":"You are a web application penetration tester conducting an authorized black-box assessment against a Node.js/React e-commerce application deployed on AWS, in scope per a signed contract. The application handles guest checkout, user accounts, and an admin portal at /admin. Describe your complete testing methodology following OWASP Testing Guide v4.2, structured in phases: reconnaissance using passive OSINT via Shodan, certificate transparency logs, and GitHub dorking for leaked API keys; automated scanning using Burp Suite Pro active scan, OWASP ZAP baseline scan, and Nuclei templates for known CVEs; manual testing of the OWASP Top 10 2021 with specific focus on A01 Broken Access Control (IDOR testing on order IDs, forced browsing to /admin), A03 Injection (SQLi via sqlmap with tamper scripts, NoSQL injection payloads for MongoDB), and A07 Identification and Authentication Failures (JWT algorithm confusion attack, session fixation). For each finding, specify the CVSS v3.1 vector string and the remediation recommendation.","tags":["penetration-testing","web-application","owasp","burp-suite","sqlmap"],"author":"AINOW","created":"2024-02-15T10:55:00Z","featured":false},

  {"id":"sec-13","title":"Active Directory Attack Chain from Low-Privilege Foothold","prompt":"You are conducting an authorized internal network penetration test for a 1,000-employee logistics company with on-premise Active Directory on Windows Server 2019 domain controllers, a legacy Windows Server 2008 R2 file server, and 800 Windows 10 workstations. You have obtained a low-privileged domain user account via a phishing simulation in scope. Document the complete attack chain from initial foothold to Domain Admin compromise, covering: AS-REP Roasting with Rubeus to crack accounts without Kerberos pre-authentication, BloodHound and SharpHound enumeration to identify the shortest path to Domain Admins, DCSync using Impacket secretsdump.py once Domain Admin is obtained, and persistence via a Golden Ticket using Mimikatz. For each step, specify the exact MITRE ATT&CK technique ID, the Windows Security Event IDs that fire with correct logging, and the specific Group Policy change that would prevent or detect each step.","tags":["penetration-testing","active-directory","bloodhound","mimikatz","red-team"],"author":"AINOW","created":"2024-02-15T11:00:00Z","featured":false},

  {"id":"sec-14","title":"AWS Cloud Penetration Test Methodology","prompt":"You are a cloud penetration tester conducting an authorized assessment of an AWS environment for a 400-person SaaS company, with written authorization including AWS penetration testing policy compliance acknowledgment. The scope includes EC2 instances, S3 buckets, Lambda functions, RDS databases, and IAM roles. Describe the complete cloud penetration testing methodology: enumeration using Pacu and ScoutSuite to identify IAM misconfigurations, overly permissive S3 bucket policies, and publicly exposed RDS snapshots; privilege escalation via IAM role assumption chaining using iam:PassRole and lambda:CreateFunction permissions as documented in Rhino Security Labs research; SSRF exploitation against EC2 IMDSv1 to retrieve instance profile credentials; and lateral movement across AWS accounts via misconfigured cross-account trust relationships. For each finding, provide the AWS CLI command that demonstrates the issue and the specific IAM policy or SCP remediation.","tags":["penetration-testing","aws","cloud-security","pacu","iam"],"author":"AINOW","created":"2024-02-15T11:05:00Z","featured":false},

  {"id":"sec-15","title":"TIBER-EU Red Team Exercise for Financial Institution","prompt":"You are the lead red team operator planning a 12-week adversary simulation exercise for a top-20 US bank, authorized under the TIBER-EU framework with CISO and board-level approval. The exercise objective is to test detection and response capabilities against a nation-state threat actor targeting wire transfer systems. Design the complete exercise plan covering: a threat intelligence preparation phase producing a TI report on realistic adversaries targeting the SWIFT messaging system, red team execution phases (initial access via spearphishing finance staff with QR code lure, establishing C2 using Cobalt Strike with domain-fronting through Azure CDN, lateral movement to the SWIFT operator workstation, simulation of a fraudulent transfer instruction without actual execution), purple team collaboration checkpoints using the Atomic Red Team test library to validate SOC detection, and the final TIBER-EU Red Team Test Report structure. Include deconfliction procedures to prevent disruption to live production banking systems.","tags":["red-team","tiber-eu","cobalt-strike","financial-services","purple-team"],"author":"AINOW","created":"2024-02-15T11:10:00Z","featured":false},

  {"id":"sec-16","title":"Android Banking App Penetration Test Using OWASP MASTG","prompt":"You are a mobile security engineer conducting an authorized penetration test of an Android banking application targeting API level 33 for a credit union, following OWASP Mobile Application Security Testing Guide v2. The app handles account balances, transfers up to $25,000, and biometric authentication. Describe your complete testing methodology: static analysis using MobSF to identify hardcoded API keys, insecure cryptographic implementations such as ECB mode or MD5 PIN hashing, and exported activities in AndroidManifest.xml; dynamic analysis using Frida to hook and bypass biometric authentication per MASVS-AUTH-2, intercept SSL traffic via Burp Suite with certificate pinning bypass scripts, and test improper session handling; and device-level testing for data leakage in SQLite databases, SharedPreferences storing sensitive tokens, and backup-enabled flags. For each MASVS category — MASVS-STORAGE, MASVS-CRYPTO, MASVS-AUTH, MASVS-NETWORK — provide one critical finding and the CVSS v3.1 score with vector string.","tags":["penetration-testing","mobile-security","android","frida","owasp-mastg"],"author":"AINOW","created":"2024-02-15T11:15:00Z","featured":false},

  {"id":"sec-17","title":"Pentest Executive Summary for Healthcare SaaS CISO","prompt":"You are a penetration testing team lead writing the executive summary section of a final report for the CISO and board of directors of a 250-person healthcare SaaS company. The authorized two-week external and internal assessment discovered: unauthenticated access to an admin API endpoint exposing all 180,000 patient records (CVSS 9.8 Critical), SQL injection in the patient search function (CVSS 8.1 High), three servers running Apache Struts with CVE-2017-5638 still unpatched (CVSS 10.0 Critical), and a weak password policy allowing the tester to crack 40% of Active Directory hashes within 4 hours using Hashcat with a custom wordlist. Write a 400-word executive summary that translates technical findings into business risk language (regulatory exposure under HIPAA, OCR breach notification thresholds, potential class action liability), provides a prioritized remediation roadmap with 30/60/90-day milestones, and frames the remediation investment against the average healthcare data breach cost of $10.9M per IBM Cost of a Data Breach 2023.","tags":["penetration-testing","reporting","executive-summary","hipaa","risk-communication"],"author":"AINOW","created":"2024-02-15T11:20:00Z","featured":false},

  {"id":"sec-18","title":"REST API Penetration Test Against Telemedicine Platform","prompt":"You are a security engineer conducting an authorized penetration test of a REST API backend for a telemedicine platform built with Python FastAPI, running on AWS API Gateway with Cognito for authentication, storing data in DynamoDB, with a Swagger UI available. Conduct a complete API security assessment following the OWASP API Security Top 10 2023: test API1:2023 Broken Object Level Authorization by enumerating appointment IDs and accessing other patients' records; API2:2023 Broken Authentication by testing JWT manipulation including algorithm confusion from RS256 to HS256 and expired token acceptance; API3:2023 Broken Object Property Level Authorization by sending unexpected fields in PUT requests to escalate account privileges; API4:2023 Unrestricted Resource Consumption by testing rate limiting with ffuf at high concurrency; and API8:2023 Security Misconfiguration by checking if Swagger UI is exposed in production with sensitive endpoint documentation. For each finding, provide the specific HTTP request/response example and the AWS API Gateway or Cognito configuration fix.","tags":["penetration-testing","api-security","owasp-api","jwt","aws"],"author":"AINOW","created":"2024-02-15T11:25:00Z","featured":true},

  {"id":"sec-19","title":"Authorized Physical and Social Engineering Assessment","prompt":"You are a security consultant conducting an authorized physical security and social engineering assessment for a financial data center operator, with explicit written authorization from the facility owner covering all activities. Design the complete assessment methodology: physical reconnaissance using OSINT on the facility address, employee LinkedIn profiles for help desk and facilities staff names, and identifying badge vendors from job postings; a tailgating attempt using a printer-delivery pretext with a cloned Mifare Classic badge produced from a brief proximity scan during a scheduled site visit; vishing the help desk using a pretext as a new employee locked out of VPN to extract a temporary password; and a USB drop test with a Rubber Ducky payload in the parking lot to measure whether employees plug in unknown devices. For each test, specify the success criteria, the detection control that should have stopped the attack, and the recommended countermeasure aligned to ISO 27001:2022 Annex A control A.7 Physical Controls.","tags":["penetration-testing","social-engineering","physical-security","vishing","iso-27001"],"author":"AINOW","created":"2024-02-15T11:30:00Z","featured":false},

  {"id":"sec-20","title":"CTF Web Exploitation Track Design for Security Training","prompt":"You are a CTF challenge designer creating a web exploitation track for an internal security training competition at a 600-person technology company, with all challenges running in an isolated Docker environment. Design five progressive web exploitation challenges: Challenge 1 Easy — a PHP application with SQL injection in the login form using MySQL where the flag is in a hidden database table; Challenge 2 Easy-Medium — a Node.js Express app with an IDOR vulnerability where changing a numeric user_id parameter reveals another user's order history; Challenge 3 Medium — a Python Flask application vulnerable to Server-Side Template Injection via Jinja2 where the flag is in an environment variable; Challenge 4 Hard — a JWT authentication bypass using the none algorithm or RS256/HS256 confusion to escalate from user to admin; Challenge 5 Hard — an SSRF vulnerability reaching the AWS EC2 Instance Metadata Service at 169.254.169.254 via IMDSv1 to retrieve IAM credentials. For each challenge, provide the learning objective, the Docker container setup, the intended solution path, and one intentional red herring.","tags":["ctf","web-exploitation","training","sql-injection","ssrf"],"author":"AINOW","created":"2024-02-15T11:35:00Z","featured":false},

  {"id":"sec-21","title":"LockBit 3.0 Ransomware Incident Response Playbook","prompt":"You are the incident response lead at a 1,500-employee manufacturing company that has just detected LockBit 3.0 ransomware encrypting files on 200 Windows workstations and three file servers at 2:47 AM. Your environment runs CrowdStrike Falcon for EDR, Cisco Umbrella for DNS security, Palo Alto firewalls, and Veeam for backups. Write a complete incident response playbook following NIST SP 800-61r2 covering all phases: Detection and Analysis (CrowdStrike alert triage, initial scope assessment using Falcon containment telemetry, identifying Patient Zero via process tree analysis), Containment (network isolation strategy preserving forensic evidence — which systems to isolate via Falcon RTR versus firewall ACL block), Eradication (identifying and removing the persistence mechanism, typically a scheduled task or registry run key), Recovery (Veeam restore sequencing starting with domain controllers, validation testing before returning to production), and Post-Incident Activity (CISA ransomware reporting, cyber insurance notification within the 72-hour policy window, lessons learned facilitation). Include decision points and escalation criteria at each phase.","tags":["incident-response","ransomware","nist-800-61","crowdstrike","forensics"],"author":"AINOW","created":"2024-02-15T11:40:00Z","featured":true},

  {"id":"sec-22","title":"Linux Web Server Forensic Investigation with Chain of Custody","prompt":"You are a DFIR analyst investigating a suspected compromise of a Linux Ubuntu 22.04 web server running Apache and a PHP application, after Wazuh SIEM alerted on unusual outbound connections to a known C2 IP. The server has been isolated from the network but remains running. Describe your complete forensic investigation maintaining chain of custody: live response data collection using LiME kernel module for memory capture before shutdown, collecting /proc filesystem artifacts, capturing network connections with ss -antp; disk imaging using dcfldd with SHA-256 hash verification to a write-protected external drive; timeline analysis using The Sleuth Kit and Autopsy to identify files created or modified in the 48 hours before detection; log analysis of /var/log/apache2/access.log for webshell access patterns and /var/log/auth.log for unauthorized SSH access; and memory analysis using Volatility 3 with linux.pslist, linux.netstat, and linux.malfind plugins. Document the evidence preservation steps required for potential legal proceedings.","tags":["forensics","incident-response","linux","volatility","dfir"],"author":"AINOW","created":"2024-02-15T11:45:00Z","featured":false},

  {"id":"sec-23","title":"Business Email Compromise Investigation in Microsoft 365","prompt":"You are a security analyst at a 300-person professional services firm investigating a BEC incident where the CFO's Microsoft 365 account was used to send fraudulent wire transfer instructions totaling $340,000 to an attacker-controlled account, discovered 18 hours after the transfer. Conduct a complete BEC incident investigation: Microsoft 365 Unified Audit Log analysis using Search-UnifiedAuditLog in PowerShell to retrieve mailbox access events, inbox rule creation forwarding emails to an external address, and OAuth application consent grants; Azure AD sign-in log analysis in Microsoft Entra ID to identify unauthorized access from unusual IP geolocation, legacy authentication protocols bypassing MFA, and impossible travel anomalies; identification of the initial access vector likely being an AiTM phishing attack using Evilginx2 to capture the post-MFA session cookie; evidence preservation for FBI IC3 complaint and cyber insurance claim. Include the specific PowerShell queries for audit log extraction and FinCEN BSA notification requirements.","tags":["incident-response","business-email-compromise","microsoft-365","forensics","financial-fraud"],"author":"AINOW","created":"2024-02-15T11:50:00Z","featured":false},

  {"id":"sec-24","title":"Insider Threat Forensic Investigation for Legal Proceedings","prompt":"You are a senior forensic investigator conducting an authorized internal investigation for a pharmaceutical company's legal and HR teams, examining a departing senior scientist suspected of exfiltrating trade secrets to a competitor. The employee had a Windows 11 workstation joined to Active Directory, used OneDrive for Business, and had VPN access to internal research file servers. Document your forensic investigation methodology: disk imaging using FTK Imager and analysis using Magnet AXIOM; registry artifact examination including NTUSER.DAT shellbags for folder access, MRU lists, and the SYSTEM hive USBSTOR key for USB device history; Windows prefetch files and LNK files showing accessed documents; OneDrive sync logs and SharePoint audit logs showing file downloads; and DLP alert correlation from Microsoft Purview showing large file transfers in the 30 days before resignation. Describe chain of custody documentation requirements for potential civil litigation under the Federal Rules of Evidence and the threshold for involving law enforcement.","tags":["forensics","insider-threat","windows-forensics","dfir","legal"],"author":"AINOW","created":"2024-02-15T11:55:00Z","featured":false},

  {"id":"sec-25","title":"AWS Cloud Incident Response for Compromised IAM Credentials","prompt":"You are a cloud security incident responder at a Series D startup when GuardDuty triggers a high-severity finding: UnauthorizedAccess:IAMUser/MaliciousIPCaller.Custom for an IAM access key belonging to a CI/CD service account, with API calls creating new IAM users and attaching AdministratorAccess policies. You have CloudTrail, VPC Flow Logs, and GuardDuty enabled across all regions. Execute the cloud incident response playbook: immediate containment by disabling the compromised key via aws iam update-access-key, attaching an explicit deny policy to the IAM user, and identifying any newly created IAM users or roles within the last 24 hours; investigation using CloudTrail Insights to enumerate all API calls made with the compromised key across all regions; blast radius assessment covering S3 GetObject events for data access, EC2 launches for cryptomining, and Lambda function creation with exfiltration code; and recovery including rotation of all secrets in AWS Secrets Manager and HashiCorp Vault. Include the Athena SQL query to reconstruct the attack timeline from CloudTrail.","tags":["incident-response","aws","cloud-security","guardduty","cloudtrail"],"author":"AINOW","created":"2024-02-15T12:00:00Z","featured":false},

  {"id":"sec-26","title":"Mass Phishing Incident Triage in Microsoft 365 Defender","prompt":"You are a SOC analyst at a 2,000-employee retail company using Microsoft 365 Defender, Proofpoint Email Security, and CrowdStrike Falcon when 45 employees report a phishing email impersonating the CEO requesting W-2 tax forms, with 8 confirmed clicks on a credential harvesting page hosted on a compromised WordPress site. Execute the complete phishing incident response: email quarantine using Microsoft 365 Defender Threat Explorer to Soft Delete all instances matching the sender and subject across all mailboxes; indicator extraction covering sender IP, envelope-from domain, link URL, and HTML payload hash; IOC blocking in Proofpoint via URL category override and CrowdStrike Custom IOC list; investigation of the 8 employees who clicked by checking Entra ID sign-in logs for successful logins from unexpected IPs within 1 hour of the click and forcing password reset and session revocation for confirmed compromises; and DNS sinkhole via Cisco Umbrella. Include the Proofpoint TAP alert webhook format and the Threat Explorer URL filter syntax.","tags":["incident-response","phishing","microsoft-365-defender","proofpoint","soc"],"author":"AINOW","created":"2024-02-15T12:05:00Z","featured":false},

  {"id":"sec-27","title":"HIPAA Breach Notification and HHS OCR Response","prompt":"You are the CISO of a 400-person healthcare technology company that has confirmed unauthorized access to a database containing PHI for 85,000 patients — including names, dates of birth, diagnosis codes, and Social Security numbers — via an unpatched Apache Log4j CVE-2021-44228 vulnerability on a public-facing API server. Develop the complete breach response and notification plan: forensic scope confirmation using database audit logs and SIEM correlation to confirm exactly what data was accessed, HIPAA Breach Notification Rule timeline (HHS OCR notification within 60 days of discovery, state AG notification for affected states including California's 72-hour CCPA window), individual notification letter requirements under HIPAA covering required content and credit monitoring offer, HHS breach portal submission process for breaches affecting 500 or more individuals, engagement of a specialized breach notification vendor, and preparation for potential class action litigation. Include a sample HHS OCR notification letter outline and the four-factor breach risk assessment methodology.","tags":["incident-response","hipaa","breach-notification","compliance","legal"],"author":"AINOW","created":"2024-02-15T12:10:00Z","featured":false},

  {"id":"sec-28","title":"Malware Analysis Workflow for Info-Stealer Sample","prompt":"You are a malware analyst at a financial institution's threat intelligence team that received a suspicious PE32+ executable from a phishing email attachment, suspected to be an info-stealer targeting browser credentials and cryptocurrency wallets. Describe your complete malware analysis workflow in a sandboxed environment: static analysis using PEStudio to examine PE headers including imports, exports, strings, and entropy indicating packing, and running FLOSS to extract obfuscated strings; behavioral analysis in Cuckoo Sandbox or ANY.RUN covering process tree, file system modifications, registry changes, and network connections to C2 infrastructure; dynamic analysis using x64dbg to unpack the first-stage loader and identify the second-stage payload decryption routine; and YARA rule creation for unique strings or byte patterns to enable retrospective hunting in CrowdStrike Falcon via custom RTR scripts. Document how to share resulting IOCs including file hashes, C2 IPs and domains, and YARA rules via MISP using STIX 2.1 format with appropriate TLP markings.","tags":["malware-analysis","forensics","yara","cuckoo","threat-intelligence"],"author":"AINOW","created":"2024-02-15T12:15:00Z","featured":false},

  {"id":"sec-29","title":"IT/OT Incident Response Tabletop for Energy Utility","prompt":"You are a security manager at a 700-person energy utility operating both IT (Microsoft 365, AWS) and OT (SCADA running GE iFIX and Wonderware, Modbus/DNP3 protocols, air-gapped historian servers) environments. Design a 4-hour tabletop exercise simulating a Volt Typhoon nation-state actor that has established persistence via a compromised VPN appliance with potential pathways to the OT network. Structure five injects: Inject 1 at T+0 — Fortinet VPN appliance anomaly detected by Darktrace; Inject 2 at T+20 minutes — discovery of living-off-the-land binaries on the IT engineering workstation that interfaces with the OT historian; Inject 3 at T+45 minutes — SCADA operator reports unusual HMI behavior; Inject 4 at T+75 minutes — media inquiry about potential grid disruption; Inject 5 at T+110 minutes — CISA Emergency Directive requiring action within 24 hours. For each inject, provide discussion questions testing the team on ICS-CERT response procedures, NERC CIP-008 incident reporting requirements, and IT/OT isolation decision-making.","tags":["incident-response","tabletop-exercise","ot-security","nerc-cip","scada"],"author":"AINOW","created":"2024-02-15T12:20:00Z","featured":false},

  {"id":"sec-30","title":"Post-Incident After-Action Report with Root Cause Analysis","prompt":"You are the incident response manager at a 900-person insurance company facilitating the post-incident review following a 72-hour Emotet and Qakbot infection that spread to 150 endpoints before containment, caused 18 hours of productivity loss, required 3 days of remediation, and cost approximately $420,000 in IR fees and lost productivity. The initial infection vector was a malicious Excel file with a macro that bypassed Symantec Endpoint Protection. Structure the complete after-action report following NIST SP 800-61r2: incident timeline reconstruction from Splunk logs, root cause analysis using the 5-Whys methodology tracing from macro execution through a GPO exception granted to the finance team in 2021, gap analysis against CIS Controls v8 IG2 controls 2.5, 9.4, and 10.2, measurable improvement actions with owners and 90-day deadlines, and KPI tracking targeting Mean Time to Detect reduction from 18 hours to 4 hours and Mean Time to Contain from 6 hours to 2 hours. Include the executive briefing structure and the formal after-action report document template.","tags":["incident-response","after-action-report","lessons-learned","nist-800-61","kpi"],"author":"AINOW","created":"2024-02-15T12:25:00Z","featured":false},

  {"id":"sec-31","title":"CIS AWS Foundations Benchmark Security Assessment","prompt":"You are a cloud security engineer at a 250-person Series B SaaS company with three AWS accounts (production, staging, development) in an AWS Organizations structure without SCPs and no formal security baseline. Conduct a comprehensive security posture assessment using the CIS AWS Foundations Benchmark v3.0. Structure your assessment across six sections: IAM (check for root account MFA, no API keys for root, password policy requiring 14+ characters, no unused credentials older than 90 days using aws iam generate-credential-report), Storage (S3 block public access at account level, S3 bucket logging, S3 SSE-KMS encryption), Logging (CloudTrail enabled in all regions with log file validation, CloudWatch alarms for root login and unauthorized API calls), Networking (no security groups allowing 0.0.0.0/0 to port 22 or 3389, VPC flow logs enabled, no default VPC in use), Monitoring (SNS for CloudTrail alerts, GuardDuty enabled across all accounts), and Remediation. For each finding, provide the AWS CLI remediation command and estimated hours to fix.","tags":["cloud-security","aws","cis-benchmark","security-posture","compliance"],"author":"AINOW","created":"2024-02-15T12:30:00Z","featured":true},

  {"id":"sec-32","title":"Microsoft 365 E5 Security Hardening and Conditional Access","prompt":"You are a cloud security architect at a 1,200-person professional services firm fully migrated to Microsoft 365 E5 and Azure, with Entra ID as the identity provider and sensitive client data in SharePoint Online and Teams. Conduct a security hardening review covering: Entra ID Conditional Access policies (require MFA for all users, block legacy authentication protocols including IMAP and SMTP that bypass MFA, require compliant device for access to sensitive SharePoint sites, enable Identity Protection Risky sign-in policy requiring MFA at Medium risk); Microsoft Secure Score improvement plan for the top 10 highest-impact E5 actions (Defender for Office 365 Safe Links and Safe Attachments, Microsoft Purview DLP for SSN and credit card patterns, Privileged Identity Management for Global Admin role assignments); Teams and SharePoint external sharing governance (restrict guest access to specific domains, require guest MFA, sensitivity labels on SharePoint sites); and Defender for Cloud Apps shadow IT discovery. Provide the Entra ID Conditional Access policy JSON templates for the three most critical policies.","tags":["cloud-security","azure","microsoft-365","conditional-access","entra-id"],"author":"AINOW","created":"2024-02-15T12:35:00Z","featured":false},

  {"id":"sec-33","title":"Kubernetes Security Hardening with Falco and Kyverno","prompt":"You are a platform security engineer at a Series C fintech company running 200 microservices on Amazon EKS 1.28, with Helm for deployments, Terraform for infrastructure, Datadog for observability, and 60 engineers with varying security awareness levels. Implement a comprehensive Kubernetes security hardening program based on CIS Kubernetes Benchmark v1.8 and NSA/CISA Kubernetes Hardening Guidance. Cover: Pod Security Standards enforcement using Kyverno with Restricted policy (no privileged containers, no hostNetwork or hostPID, required securityContext with runAsNonRoot, readOnlyRootFilesystem, dropped CAP_ALL capabilities), Calico network policies with default-deny and explicit namespace-level allow rules, RBAC least-privilege audit using rbac-lookup and kubectl-who-can to identify overly permissive ClusterRoleBindings, secrets management migration from base64 Kubernetes Secrets to HashiCorp Vault with the Vault Agent Injector sidecar pattern, and runtime threat detection using Falco with custom rules for detecting kubectl exec into running pods and cryptomining process names. Provide the Kyverno Restricted policy YAML and the Falco rule for detecting shells spawned in containers.","tags":["cloud-security","kubernetes","eks","falco","kyverno"],"author":"AINOW","created":"2024-02-15T12:40:00Z","featured":false},

  {"id":"sec-34","title":"CSPM Program Implementation with Wiz for Multi-Cloud HIPAA","prompt":"You are a security engineer at a healthcare technology company operating a multi-cloud environment (60% AWS, 30% Azure, 10% GCP) with 400 cloud accounts, using Wiz as your Cloud Security Posture Management platform. Design the CSPM program implementation: initial onboarding and baseline scanning to identify public S3 buckets with PHI, publicly exposed databases, overly permissive IAM roles, and unencrypted snapshots; custom policy creation in Wiz for HIPAA-relevant controls (encryption at rest for all RDS instances, audit logging enabled, no public network exposure for PHI-tagged resources); integration with GitHub Actions using Wiz CLI to fail infrastructure-as-code pull requests introducing critical misconfigurations via Terraform IaC scanning; Jira workflow integration for automatic ticket creation with 48-hour SLA for Critical findings and 7-day SLA for High findings; and executive reporting dashboard showing compliance posture trending across HIPAA, CIS AWS, and SOC 2 Trust Service Criteria. Include the Wiz CLI GitHub Actions workflow YAML snippet.","tags":["cloud-security","cspm","wiz","hipaa","multi-cloud"],"author":"AINOW","created":"2024-02-15T12:45:00Z","featured":false},

  {"id":"sec-35","title":"IAM Privilege Escalation Remediation in AWS Organizations","prompt":"You are a cloud security engineer at an e-commerce company processing $50M annually on AWS, where a security audit identified 23 IAM privilege escalation paths using Cloudsploit and PMapper, including 6 paths leading to full administrator access. Design a comprehensive IAM remediation program: use AWS IAM Access Analyzer to identify policies granting access to external principals and generate least-privilege recommendations from CloudTrail activity; implement Service Control Policies to prevent the riskiest IAM actions across all accounts (deny iam:CreatePolicyVersion, iam:SetDefaultPolicyVersion, iam:PassRole to wildcard, and iam:CreateAccessKey for other users); deploy IAM Identity Center replacing long-term IAM user credentials for all human users; implement just-in-time access for privileged roles using IAM Identity Center's temporary elevated access request feature; and establish continuous monitoring using Steampipe with the AWS IAM mod for daily privilege escalation path checks. Provide the SCP JSON blocking the top five privilege escalation techniques from Rhino Security Labs research.","tags":["cloud-security","aws","iam","privilege-escalation","scp"],"author":"AINOW","created":"2024-02-15T12:50:00Z","featured":false},

  {"id":"sec-36","title":"GCP Security Configuration Review for SOC 2 Compliance","prompt":"You are a security architect at a 150-person analytics startup running entirely on Google Cloud Platform — GKE for compute, BigQuery for analytics containing customer behavioral data, Cloud Storage for data lake, Cloud SQL for transactions, and Google Workspace — subject to SOC 2 Type II certification. Conduct a GCP security configuration review aligned to CIS Google Cloud Platform Foundation Benchmark v2.0: Organization Policy review (enforce uniform bucket-level access, disable VM serial port access, require OS Login for SSH to GCE instances, restrict public IP on Cloud SQL); IAM audit (identify users with primitive Owner or Editor roles at project level, service accounts with project-level Owner binding, external identities with organization-level roles); Cloud Logging review (log sink to Cloud Storage for long-term retention, metric alerts for audit config changes and project ownership changes); BigQuery security (column-level security using policy tags for PII fields, authorized views for row-level access, VPC Service Controls perimeter to prevent data exfiltration). Provide the gcloud CLI commands to remediate the top five findings.","tags":["cloud-security","gcp","cis-benchmark","bigquery","soc2"],"author":"AINOW","created":"2024-02-15T12:55:00Z","featured":false},

  {"id":"sec-37","title":"Secure Container Image Supply Chain with Trivy and Cosign","prompt":"You are a DevSecOps engineer at a 400-person SaaS company building a secure container image supply chain for 80 microservices deployed to AWS EKS, using GitHub Actions for CI/CD and Amazon ECR for the image registry, with no image scanning currently in place. Design the complete container image security pipeline: base image hardening policy using only distroless or Alpine-based images from a curated ECR private registry scanned weekly with Trivy; shift-left scanning in GitHub Actions using Trivy to scan Dockerfiles and image layers on every PR and fail the build on Critical CVEs with CVSS 9.0 or higher without an approved exception; Dockerfile security linting using Hadolint enforcing no running as root, no ADD instruction for remote URLs, and explicit USER declaration; image signing using AWS Signer and cosign with a Kyverno policy to enforce that only signed pipeline images deploy to EKS; and SBOM generation using Syft in CycloneDX format stored in S3 for each image version. Provide the complete GitHub Actions workflow YAML for the security scanning stage.","tags":["cloud-security","devsecops","container-security","trivy","sbom"],"author":"AINOW","created":"2024-02-15T13:00:00Z","featured":false},

  {"id":"sec-38","title":"AWS KMS Data Encryption Strategy for Financial Services","prompt":"You are a cloud security architect at a financial services company with $2B AUM, running on AWS with Aurora PostgreSQL holding client investment data, S3 containing trade confirmations and statements, and DynamoDB for real-time account balances, subject to SEC Regulation S-P, GLBA Safeguards Rule, and SOC 2 Type II. Design the comprehensive data protection and encryption strategy: AWS KMS key management structure using separate CMKs per data classification (client PII, financial transaction data, audit logs) with automatic key rotation, key access limited to specific IAM roles, and CloudTrail logging for all key usage; Aurora database encryption with KMS; application-level encryption for SSN and account numbers using AWS Encryption SDK with envelope encryption before data reaches the database; S3 SSE-KMS with bucket key for cost optimization; and DynamoDB encryption with AWS managed keys. Include the KMS key policy JSON showing least-privilege access for a Lambda function that reads encrypted S3 objects, and the AWS Encryption SDK Python envelope encryption pattern.","tags":["cloud-security","encryption","aws-kms","data-protection","financial-services"],"author":"AINOW","created":"2024-02-15T13:05:00Z","featured":false},

  {"id":"sec-39","title":"AWS Multi-Account Security Reference Architecture","prompt":"You are a principal cloud architect at a 2,000-employee enterprise migrating 200 applications to AWS over 18 months, currently with a single AWS account and broadly granted IAM permissions. Design a target multi-account architecture following the AWS Security Reference Architecture and AWS Organizations best practices: account structure with a Security OU containing Log Archive and Security Tooling accounts, an Infrastructure OU with Network and Shared Services accounts, and Workload OUs segmented by business unit and environment; centralized security services using GuardDuty in delegated admin mode from Security Tooling, Security Hub with CIS AWS Benchmark standard, AWS Config with conformance packs across all accounts, and Macie for S3 PII discovery in production; network architecture using a centralized inspection VPC with AWS Network Firewall and Palo Alto VM-Series in the Network account, AWS Transit Gateway for inter-VPC routing, and no direct internet access from workload VPCs; and IAM Identity Center federated from Okta SAML. Provide the AWS Organizations SCP hierarchy and Terraform module structure for deploying the security baseline.","tags":["cloud-security","aws","organizations","security-reference-architecture","terraform"],"author":"AINOW","created":"2024-02-15T13:10:00Z","featured":true},

  {"id":"sec-40","title":"Cryptomining Attack Detection and Cloud Cost Recovery","prompt":"You are a cloud security engineer at a startup when AWS Cost Explorer shows a $47,000 unexpected charge with Compute costs up 800% overnight — dozens of p3.16xlarge GPU instances are running in regions you never use, and GuardDuty has fired CryptoCurrency:EC2/BitcoinTool.B findings. Execute the complete investigation and response: immediate containment by identifying all unauthorized EC2 instances using aws ec2 describe-instances across all regions filtered by launch time, terminating unauthorized instances, and disabling the IAM credentials used to launch them; root cause investigation using CloudTrail to trace the source API call back to the IAM principal and identifying the credential exposure method via TruffleHog scans of GitHub repositories and checks for exposed .env files in S3; blast radius assessment examining what other API calls were made — S3 data exfiltration, new IAM user creation, Lambda function deployment; recovery by rotating all affected credentials and implementing AWS Cost Anomaly Detection with a $500 threshold alert; and the AWS billing credit request process for unauthorized usage. Include the AWS CLI cross-region instance discovery command sequence.","tags":["cloud-security","incident-response","aws","cryptomining","cost-anomaly"],"author":"AINOW","created":"2024-02-15T13:15:00Z","featured":false},

  {"id":"sec-41","title":"Secure Code Review for Python Authentication Service","prompt":"You are a security engineer at a 300-person fintech company conducting a secure code review of a newly written Python FastAPI authentication service handling login, session management, and password reset for 50,000 customers, using JWT for session tokens, bcrypt for password hashing, and PostgreSQL. Review implementation areas against OWASP Top 10 2021 A07 Identification and Authentication Failures: JWT implementation (verify algorithm is explicitly set to RS256 and not taken from the token header, verify token expiry is enforced, confirm access token lifetime is 15 minutes and refresh token is 7 days with rotation); password hashing (bcrypt work factor of 12 or higher, timing-safe comparison for hash verification); password reset flow (secrets.token_urlsafe(32) for tokens, 1-hour expiry, invalidation of used tokens, no email enumeration via timing oracle); and brute force protection (slowapi rate limiting, account lockout after 10 failures with exponential backoff). For each finding, provide the vulnerable code pattern, the secure alternative, and the OWASP ASVS v4.0 verification requirement number.","tags":["application-security","secure-code-review","authentication","python","owasp-asvs"],"author":"AINOW","created":"2024-02-15T13:20:00Z","featured":true},

  {"id":"sec-42","title":"Semgrep and Checkmarx SAST Integration into GitHub Actions","prompt":"You are a DevSecOps engineer at a 500-person healthcare technology company with 30 engineering teams deploying Java Spring Boot, Python Flask, and React applications via GitHub Actions, needing HITRUST CSF certification requiring evidence of automated security testing in the SDLC. Design and implement a SAST program: tool selection rationale covering Semgrep for custom rule development, Checkmarx One for Java CWE coverage, and SonarQube Security Hotspot rules; GitHub Actions workflow configuration running Semgrep on every PR with rules from the semgrep-rules registry filtered to p/java p/python p/react, failing PRs on High confidence findings, and posting inline annotations on the diff; Checkmarx query customization to remove false positives from Spring Security configuration with suppression audit trail; findings management via Jira integration with SLA of 5 business days for Critical and 30 days for High; and HITRUST evidence package generation showing control 09.ab coverage. Provide the GitHub Actions YAML for Semgrep integration with SARIF output uploaded to GitHub Advanced Security.","tags":["application-security","sast","devsecops","semgrep","github-actions"],"author":"AINOW","created":"2024-02-15T13:25:00Z","featured":false},

  {"id":"sec-43","title":"Public Bug Bounty Program Launch on HackerOne","prompt":"You are the head of product security at a Series D SaaS company with 5,000 enterprise clients, launching a public bug bounty on HackerOne after a 6-month private program with 20 researchers. Design the complete program: scope definition (in-scope: app.company.com, iOS and Android apps, api.company.com; out-of-scope: third-party integrations, customer-hosted instances, social engineering, DoS testing); reward structure (Critical CVSS 9.0+ RCE or auth bypass: $10,000–$25,000; High CVSS 7.0–8.9 SQLi, SSRF, privilege escalation: $2,500–$10,000; Medium CVSS 4.0–6.9 XSS or IDOR: $500–$2,500; Low: $100–$500); response SLA commitments (triage within 3 business days, updates every 7 days); coordinated disclosure policy with 90-day deadline before public release; internal triage process via HackerOne to Jira integration with CVSS scoring using environmental modifiers for your context; and legal safe harbor language. Include the safe harbor statement text and the criteria for P1 escalation to the incident response team.","tags":["application-security","bug-bounty","hackerone","vulnerability-disclosure","product-security"],"author":"AINOW","created":"2024-02-15T13:30:00Z","featured":false},

  {"id":"sec-44","title":"OWASP Top 10 Developer Security Training Curriculum","prompt":"You are a security champion program lead at a 600-engineer software company building web applications in React, Node.js, and Go, where the last penetration test found 8 High-severity OWASP Top 10 vulnerabilities and the engineering team has no formal security training. Design a 10-module developer security training curriculum with one module per OWASP Top 10 2021 category, each as a 90-minute hands-on session: 20 minutes of concept explanation with real CVE examples from production breaches (for A03 Injection, reference CVE-2021-44228 Log4Shell and the 2022 Optus SQLi breach), 45 minutes of hands-on lab exploiting vulnerabilities in DVWA, WebGoat, or Juice Shop running in Docker, 15 minutes of code fix workshop showing secure implementation in Node.js and Go (parameterized queries with node-postgres, input validation with Zod, output encoding with DOMPurify), and 10 minutes of quiz with LMS certificate tracking. For the A01 Broken Access Control module, design the lab exercise using Juice Shop's IDOR challenge and the corresponding Node.js middleware fix pattern.","tags":["application-security","developer-training","owasp-top-10","secure-coding","security-champions"],"author":"AINOW","created":"2024-02-15T13:35:00Z","featured":false},

  {"id":"sec-45","title":"OWASP ZAP DAST Integration for Jenkins CI/CD Pipeline","prompt":"You are an application security engineer at a 400-person insurance technology company running 15 web applications and 30 APIs via a Jenkins-based CI/CD pipeline on AWS, needing SOC 2 Type II CC6.8 control evidence for automated security testing. Design a DAST program: tool deployment using OWASP ZAP in daemon mode for authenticated scanning, Burp Suite Enterprise for scheduled production clone scans, and Nuclei for fast CVE-based scanning of public endpoints; Jenkins pipeline integration with ZAP baseline scan on every staging deployment (15-minute passive scan), ZAP full active scan weekly against staging with results in JUnit XML format to fail builds on High findings; authenticated scanning configuration for OAuth 2.0 login via ZAP script to obtain Okta access tokens and inject Authorization headers; API security testing using ZAP's OpenAPI/Swagger import to enumerate all endpoints and test for authentication bypass, mass assignment, and injection; and findings deduplication to suppress known accepted risks. Provide the ZAP API scan GitHub Actions workflow and the custom scan policy XML for the insurance application risk profile.","tags":["application-security","dast","owasp-zap","jenkins","soc2"],"author":"AINOW","created":"2024-02-15T13:40:00Z","featured":false},

  {"id":"sec-46","title":"Snyk SCA and Dependency Management Program","prompt":"You are a security engineer at a 250-person SaaS company with 45 repositories using npm, pip, and Maven, where an audit found 340 vulnerabilities in third-party dependencies including 12 Critical CVEs and no process for dependency updates. Build a Software Composition Analysis and dependency management program: tool deployment using Snyk integrated with GitHub for PR-level scanning with automatic PR comments and blocking of Critical introductions, OWASP Dependency-Check for Maven in Jenkins, and Dependabot for automated minor and patch update PRs; policy definition (no direct dependencies with Critical CVEs in the CISA KEV catalog without CISO approval; High CVEs remediated within 30 days; transitive vulnerabilities in the top 3 dependency levels within 90 days); remediation prioritization combining CVSS score, Snyk reachability analysis, and EPSS score above 0.5; license compliance policy enforced via FOSSA (Apache 2.0, MIT, BSD permitted; AGPL prohibited in commercial products); and a private package registry using AWS CodeArtifact to prevent dependency confusion attacks. Provide the .snyk policy file syntax for accepting a false positive.","tags":["application-security","sca","snyk","dependency-management","supply-chain"],"author":"AINOW","created":"2024-02-15T13:45:00Z","featured":false},

  {"id":"sec-47","title":"Scalable Threat Modeling Program for 50 Agile Squads","prompt":"You are a product security engineer at a 700-person healthcare SaaS company introducing threat modeling into the SDLC for the first time, with 50 agile squads shipping bi-weekly, using Jira for project management and Confluence for documentation. Design a pragmatic threat modeling program that scales without creating a bottleneck: a lightweight Confluence template using STRIDE-per-element for the top three highest-risk data flows per feature rather than every code change; a Security Design Review checklist of 20 yes-or-no questions answered during sprint planning for features touching PHI or authentication (covering authentication method, authorization model, data encryption, PHI access logging, and input validation); a high-risk trigger list requiring a mandatory full STRIDE threat model with the AppSec team (new external API integrations, changes to authentication flows, new data retention features, new PHI access code paths); threat model documentation in OWASP Threat Dragon format stored in the feature's Jira epic; and metrics tracking program maturity (percentage of high-risk features with completed threat models, number of threats identified pre-code versus in pentest). Provide the 20-question Security Design Review checklist.","tags":["application-security","threat-modeling","sdlc","owasp","security-champions"],"author":"AINOW","created":"2024-02-15T13:50:00Z","featured":false},

  {"id":"sec-48","title":"Stored XSS Remediation and Content Security Policy Deployment","prompt":"You are a security engineer at a 200-person media company with a React-based CMS storing and serving user-generated HTML content to 2 million monthly visitors, where a pentest found a stored XSS in the comment system scoring CVSS 8.2 that enables session cookie theft. Design the comprehensive XSS remediation and prevention program: immediate fix using DOMPurify with a strict allowlist (permitted tags: p, br, strong, em, a with href restricted to http/https only; strip all event handlers and javascript: URIs); Content Security Policy implementation with a nonce-based approach for inline scripts (default-src 'self'; script-src 'nonce-{random}'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'); CSP deployment strategy starting in Report-Only mode collecting violations via report-uri.com for 2 weeks before enforcing, with strict-dynamic for Google Analytics and Intercom exceptions; React-specific XSS prevention auditing all dangerouslySetInnerHTML usage and enforcing ESLint plugin react-security in CI; and HTTPOnly and Secure cookie flags for all session cookies. Provide the DOMPurify configuration object and the final enforced CSP header value.","tags":["application-security","xss","content-security-policy","react","owasp"],"author":"AINOW","created":"2024-02-15T13:55:00Z","featured":false},

  {"id":"sec-49","title":"Secrets Detection and HashiCorp Vault Migration Program","prompt":"You are a security engineer at a 350-person fintech company that discovered 47 AWS access keys, 12 database passwords, and 3 Stripe API keys committed to GitHub repositories over two years via a retrospective scan, with two confirmed exploitation incidents tracing to leaked GitHub secrets. Build a comprehensive secrets management remediation and prevention program: emergency response by revoking all confirmed live credentials immediately, using git-filter-repo or BFG Repo-Cleaner to remove secrets from git history across affected repositories, and notifying GitHub Security for cache purge; secrets detection pipeline using TruffleHog GitHub Action in --verified mode on every PR and pre-commit, detect-secrets hooks with a baseline file for known false positives, and GitHub Advanced Security Secret Scanning with push protection enabled; secrets management migration target using HashiCorp Vault for application secrets with AppRole authentication from Kubernetes pods, AWS Secrets Manager for RDS credentials with automatic rotation, and GitHub Actions secrets for CI/CD variables; and developer education via lunch-and-learn sessions and documentation of approved secrets retrieval patterns per language. Provide the TruffleHog GitHub Actions YAML and the Vault AppRole authentication Python snippet.","tags":["application-security","secrets-management","trufflehog","hashicorp-vault","devsecops"],"author":"AINOW","created":"2024-02-15T14:00:00Z","featured":true},

  {"id":"sec-50","title":"FAPI 2.0 Open Banking API Security Design Review","prompt":"You are a principal security engineer reviewing the API design for a new Open Banking API at a regional bank with 400,000 customers, subject to PSD2 regulations and the FAPI 2.0 Security Profile. The API allows third-party providers to access customer account data and initiate payments with customer consent. Conduct a complete API security design review: authentication and authorization using OAuth 2.0 with PKCE for public clients, Pushed Authorization Requests (PAR) to prevent authorization code injection, mTLS sender-constrained tokens, and JWT Secured Authorization Response Mode (JARM); rate limiting design with per-client limits of 100 requests per minute for account data and 10 per minute for payment initiation with HTTP 429 and Retry-After headers; input validation using OpenAPI schema validation as middleware with response filtering to never expose internal system fields; PSD2 Article 98 audit trail logging covering all consent grants and revocations, payment initiation attempts with outcome, and data access events with TPP client ID and timestamp at 5-year retention; and PSD2 Strong Customer Authentication implementation using FIDO2 WebAuthn. Provide the OAuth 2.0 authorization server configuration requirements and the PAR endpoint specification.","tags":["application-security","api-security","oauth2","open-banking","fapi"],"author":"AINOW","created":"2024-02-15T14:05:00Z","featured":false},

  {"id":"sec-51","title":"Zero Trust Architecture Roadmap for Hybrid Enterprise","prompt":"You are a security architect at a 2,500-employee financial services company with a hybrid infrastructure — 60% on-premise Windows Active Directory, 40% on Azure — using Zscaler for web gateway, CrowdStrike Falcon for EDR, and Okta as the identity provider, currently operating a flat trusted-network model with no micro-segmentation. Design a 4-phase Zero Trust Architecture roadmap following NIST SP 800-207 and CISA Zero Trust Maturity Model v2.0: Phase 1 (months 1–3) covering identity pillar foundation by enforcing MFA on all Okta applications, deploying Okta Device Trust to require managed devices, and eliminating standing privileged access for 50 AD admin accounts via PAM; Phase 2 (months 4–6) covering device pillar using CrowdStrike Zero Trust Assessment scores as a Conditional Access signal in Okta, enforcing Intune compliance policy for all Windows endpoints; Phase 3 (months 7–9) covering network pillar deploying Zscaler Private Access to replace legacy VPN for all internal application access; Phase 4 (months 10–12) covering application and data pillar implementing microsegmentation in Azure with NSG flow logs and deploying Microsoft Purview sensitivity labels. Provide the maturity level mapping, success metrics per phase, and the estimated FTE effort.","tags":["identity","zero-trust","okta","nist-800-207","zscaler"],"author":"AINOW","created":"2024-02-15T14:10:00Z","featured":true},

  {"id":"sec-52","title":"Privileged Access Management Implementation with CyberArk","prompt":"You are an IAM security engineer at a 1,800-person healthcare organization subject to HIPAA and HITRUST CSF, where a recent audit found 340 shared privileged accounts, 120 local admin accounts on servers, and no session recording for privileged access to the Epic EHR database servers. Design a Privileged Access Management implementation using CyberArk Privileged Access Security: vault architecture and high-availability deployment for 500 managed accounts; onboarding priority (Tier 0: domain admin and EA accounts in Active Directory, Tier 1: local admin on all Windows Server 2022 servers, Tier 2: service accounts with hard-coded passwords in 200 applications); CyberArk Conjur for application-to-application password management replacing hard-coded credentials in Java microservices; PSM (Privileged Session Manager) deployment for full session recording and keystroke logging on all Epic database administrator sessions stored for 1-year HIPAA audit retention; just-in-time access workflow using CyberArk Alero for vendor third-party privileged access with time-limited credentials; and integration with ServiceNow for approval workflows. Provide the CyberArk account onboarding policy template and the HITRUST control mapping for PAM controls.","tags":["identity","pam","cyberark","hipaa","privileged-access"],"author":"AINOW","created":"2024-02-15T14:15:00Z","featured":false},

  {"id":"sec-53","title":"Okta SSO and MFA Deployment for 3,000 Users","prompt":"You are an identity architect at a 3,000-person manufacturing company migrating from on-premise Active Directory with password-only authentication to Okta Workforce Identity Cloud as the SSO and MFA platform, with 150 SaaS applications and 40 on-premise applications requiring SSO integration. Design the complete Okta deployment: Active Directory integration using Okta AD Agent with Universal Sync for user provisioning (sync every 5 minutes, passwordless hash sync disabled for security), MFA enrollment campaign (FIDO2 WebAuthn as primary factor for all users, Okta Verify push as fallback, SMS OTP prohibited due to SIM-swapping risk, 30-day enrollment window with manager reporting on non-compliant users); Conditional Access policies using Okta's Sign-On Policy (require FIDO2 for privileged Okta admin roles, require Okta Verify push for standard users, allow IP-based trusted network exclusion only for legacy printers and service accounts); SAML 2.0 integration for the top 20 SaaS applications (Salesforce, Workday, ServiceNow) with SCIM provisioning for automated user lifecycle; and a phased application onboarding roadmap. Provide the Okta Sign-On Policy JSON for the FIDO2 enforcement rule and the AD Agent deployment checklist.","tags":["identity","okta","sso","mfa","active-directory"],"author":"AINOW","created":"2024-02-15T14:20:00Z","featured":false},

  {"id":"sec-54","title":"OAuth 2.0 and OIDC Security Implementation Review","prompt":"You are a security engineer at a 400-person SaaS company whose platform allows enterprise customers to integrate via OAuth 2.0 authorization code flow, and whose mobile app uses OIDC for user authentication with an Okta authorization server. Conduct a security review of the OAuth 2.0 and OIDC implementation covering: authorization code flow security (PKCE required for all public clients to prevent authorization code interception, state parameter entropy of 128 bits minimum to prevent CSRF, redirect_uri exact match validation to prevent open redirect abuse); token security (access tokens as opaque references validated at the resource server via Okta introspection endpoint rather than local JWT validation, refresh token rotation with reuse detection enabled in Okta, refresh token absolute lifetime of 30 days); client credential management (no client_secret embedded in mobile app binaries — use PKCE-only flow, rotate client secrets annually for confidential clients, revoke and reissue for suspected compromise); scope minimization (define resource-specific scopes such as patient:read and payment:write rather than broad admin scope, require explicit customer consent UI for third-party apps); and threat scenarios from the OAuth Security Best Current Practice RFC 9700. Provide the Okta authorization server settings for token rotation and the PKCE code challenge generation code in JavaScript.","tags":["identity","oauth2","oidc","okta","api-security"],"author":"AINOW","created":"2024-02-15T14:25:00Z","featured":false},

  {"id":"sec-55","title":"Active Directory Security Hardening and Tiering Model","prompt":"You are a security architect at a 2,000-employee professional services firm where a red team exercise demonstrated a path from a standard user to Domain Admin in 4 hours via Kerberoasting and unconstrained delegation abuse, exploiting a flat Active Directory structure with no tiering. Design a comprehensive Active Directory security hardening program: implement the Microsoft Enterprise Access Model (formerly tier model) with Tier 0 covering domain controllers and AD administration, Tier 1 covering server administration, Tier 2 covering workstation and user administration — each with separate admin accounts and PAWs (Privileged Access Workstations); disable unconstrained Kerberos delegation on all accounts (audit with Get-ADComputer -Filter {TrustedForDelegation -eq $true}); enable Protected Users security group for all Tier 0 and Tier 1 admin accounts (prevents NTLM auth, DES/RC4 Kerberos, unconstrained delegation); deploy Microsoft Defender for Identity (MDI) to detect Kerberoasting, DCSync, and Pass-the-Hash attacks with integration to Microsoft Sentinel; audit and remove Service Principal Names from user accounts that are Kerberoastable with weak passwords; and enforce LAPS (Local Administrator Password Solution) for all workstations and member servers. Provide the PowerShell script to identify all Kerberoastable accounts with their password age.","tags":["identity","active-directory","kerberos","microsoft-defender-for-identity","hardening"],"author":"AINOW","created":"2024-02-15T14:30:00Z","featured":false},

  {"id":"sec-56","title":"Service Account and Non-Human Identity Governance","prompt":"You are an IAM engineer at a 1,500-person financial services company that has 3,200 service accounts in Active Directory — 40% with passwords over 2 years old, 60% with Domain Admin or overly broad permissions, and 200 with non-expiring passwords — plus 800 cloud service accounts across AWS IAM and Azure service principals with no inventory or lifecycle management. Design a Non-Human Identity (NHI) governance program: discovery and inventory of all service accounts across AD (PowerShell AD module), AWS (aws iam list-users filtered by service tag convention), Azure (az ad sp list), and Kubernetes (kubectl get serviceaccounts across all namespaces) into a ServiceNow CMDB with owner, purpose, and last-used date fields; risk scoring model (unused 90+ days: High, non-expiring password: Medium, broad permissions: Critical, no owner: High); remediation workflow (disable unused accounts after 30-day grace period with owner notification, rotate all AD service account passwords via CyberArk, convert eligible AD service accounts to Group Managed Service Accounts for automatic password rotation, replace AWS long-term IAM access keys with IAM roles); and quarterly recertification process. Provide the PowerShell command to find all AD service accounts with passwords older than 180 days and no recent logon.","tags":["identity","service-accounts","non-human-identity","iam","governance"],"author":"AINOW","created":"2024-02-15T14:35:00Z","featured":false},

  {"id":"sec-57","title":"FIDO2 Passwordless Authentication Rollout","prompt":"You are an identity security engineer at a 5,000-person retail company that experiences 300 helpdesk password reset tickets monthly at $25 per ticket cost, has suffered two credential-stuffing attacks in 18 months, and wants to move to passwordless authentication using FIDO2 WebAuthn with Okta as the identity provider and a mix of Windows 11 and macOS Sonoma endpoints. Design the FIDO2 passwordless deployment: hardware security key selection rationale (YubiKey 5 Series for privileged users and executives, platform authenticators (Windows Hello for Business, macOS Touch ID) for standard users to minimize cost); Windows Hello for Business deployment via Intune (Hybrid Azure AD Join configuration, WHfB policy requiring PIN complexity, TPM required); Okta FastPass configuration as a phishing-resistant authenticator that meets NIST AAL2 requirements; enrollment campaign design (IT self-service enrollment kiosk, 60-day rollout by department, identity verification requirement for initial FIDO2 key binding to prevent account takeover during enrollment); and fallback strategy for FIDO2 device loss (backup FIDO2 key policy for privileged users, temporary access code process through verified identity workflow). Provide the Intune Windows Hello for Business configuration profile JSON and the estimated annual cost savings calculation.","tags":["identity","fido2","passwordless","okta","windows-hello"],"author":"AINOW","created":"2024-02-15T14:40:00Z","featured":false},

  {"id":"sec-58","title":"Identity Threat Detection with Microsoft Entra ID Protection","prompt":"You are a security operations engineer at a 2,000-person technology company fully on Microsoft 365 E5, with Entra ID as the identity provider, 200 daily risky sign-in events in Identity Protection that the SOC has no structured process to triage, and a recent AiTM phishing attack that bypassed legacy MFA and resulted in a BEC incident. Design a structured identity threat detection and response program using Microsoft Entra ID Protection: risk policy configuration (User risk policy: block access and require password reset at High risk; Sign-in risk policy: require MFA at Medium risk; named location exclusion for corporate IP ranges only with documented approval process); Microsoft Sentinel integration for identity-focused detection rules (impossible travel combined with session-cookie-based access, new country sign-in followed by mailbox rule creation within 30 minutes, OAuth app consent to unusual permissions); automated response playbook in Microsoft Sentinel SOAR (Logic App workflow: High risk user detected → disable user in Entra ID → revoke all refresh tokens → create ServiceNow P1 incident → notify manager and security team); and monthly Identity Secure Score review process targeting 85% or above. Provide the Sentinel KQL detection rule for AiTM phishing indicators (token replay from two different IP addresses within 5 minutes).","tags":["identity","entra-id","microsoft-sentinel","identity-threat-detection","aitm-phishing"],"author":"AINOW","created":"2024-02-15T14:45:00Z","featured":false},

  {"id":"sec-59","title":"IAM Access Review and Certification Automation","prompt":"You are an identity governance engineer at a 4,000-person healthcare company subject to HIPAA minimum necessary access requirements and SOC 2 Type II, where quarterly access reviews are conducted manually via spreadsheet, taking 3 weeks per cycle, resulting in 70% rubber-stamp approvals with no meaningful review by 800 managers. Design an automated access review and certification program using SailPoint IdentityNow: access review campaign configuration (quarterly campaigns for privileged access, annual campaigns for standard application access, triggered campaigns 30 days after role change or promotion); risk-based prioritization to surface only the 20% of access that carries highest risk (focus manager attention on privileged roles, toxic combinations such as Accounts Payable plus payment approval in Workday, access to sensitive PHI repositories in SharePoint); automated remediation for non-responses (auto-revoke after 14 days of manager non-response for standard access, escalate to skip-level manager for privileged access after 7 days); integration with Active Directory, Okta, Salesforce, and Epic EHR via SailPoint connectors for automated de-provisioning; and reporting dashboard for HIPAA audit evidence showing access review completion rate and remediation actions taken. Provide the SailPoint campaign filter configuration for identifying toxic access combinations.","tags":["identity","access-review","sailpoint","hipaa","governance"],"author":"AINOW","created":"2024-02-15T14:50:00Z","featured":false},

  {"id":"sec-60","title":"Customer Identity and Access Management Security Design","prompt":"You are a security architect at a Series C e-commerce company with 5 million customer accounts, using Auth0 as the Customer Identity and Access Management (CIAM) platform, experiencing 50,000 credential-stuffing attempts daily and 200 account takeover incidents monthly, with customers losing an average of $180 per compromised account. Design a comprehensive CIAM security hardening program: credential stuffing defense using Auth0 Attack Protection (breached password detection via HaveIBeenPwned API integration, bot detection using Auth0's IP rate limiting and CAPTCHAv3 challenge threshold configuration, suspicious IP throttling); account takeover prevention (step-up authentication for high-risk actions such as password change, email change, and shipping address change requiring SMS OTP or email verification regardless of MFA enrollment status, transaction anomaly detection for purchases over $500 or new device); customer MFA enrollment incentive program (optional TOTP via Google Authenticator or FIDO2 passkey, discount incentive for MFA enrollment, MFA enforcement for accounts with stored payment methods); login security UI improvements (clear password-breach notification, trusted device management dashboard, active session list with remote logout capability); and breach response automation (automated account lock on 10 failed attempts, credential-stuffing pattern detection triggering captcha challenge for entire login flow). Provide the Auth0 Attack Protection configuration and the step-up authentication rule in Auth0 Actions JavaScript.","tags":["identity","ciam","auth0","credential-stuffing","account-takeover"],"author":"AINOW","created":"2024-02-15T14:55:00Z","featured":false},

  {"id":"sec-61","title":"SOC 2 Type II Readiness Assessment and Remediation Plan","prompt":"You are a security compliance manager at a 180-person B2B SaaS company processing financial data for 800 enterprise customers, preparing for your first SOC 2 Type II audit with a Big 4 audit firm in 9 months. Your current security posture has never been formally assessed. Conduct a SOC 2 Type II readiness assessment against the AICPA Trust Services Criteria, focusing on CC6 Logical and Physical Access Controls and CC7 System Operations. For each of the 33 Common Criteria, identify: the current control state (Designed and Operating, Designed but Not Operating, Not Designed), the evidence required by auditors (policy documents, configuration screenshots, access review records, log samples), the remediation steps and responsible team, and the implementation timeline. Specifically address gaps most commonly found in first-time SOC 2 audits: lack of formal change management process (CC8.1), no formal vendor risk management program (CC9.2), incomplete background check process for all personnel with system access (CC1.1), and absence of continuous monitoring evidence for security alerts. Provide the gap assessment table and a 9-month project plan with audit milestones.","tags":["compliance","soc2","trust-services-criteria","risk-management","audit"],"author":"AINOW","created":"2024-02-15T15:00:00Z","featured":true},

  {"id":"sec-62","title":"ISO 27001:2022 Implementation Roadmap","prompt":"You are a Chief Information Security Officer at a 600-person professional services firm that has committed to ISO 27001:2022 certification within 18 months to meet enterprise customer contract requirements, starting from a baseline of informal security practices and no documented ISMS. Design the complete ISO 27001:2022 implementation roadmap: Phase 1 (months 1–3) covering scope definition per clause 4.3, context of the organization and interested parties analysis, preliminary risk assessment using the ISO 27005 framework, and executive leadership commitment and Statement of Applicability draft; Phase 2 (months 4–9) covering the 93 Annex A controls gap assessment (highlighting new controls in ISO 27001:2022 including A.5.7 Threat Intelligence, A.8.8 Management of Technical Vulnerabilities, A.5.23 Information Security for Cloud Services), information security policy suite development (ISMS policy, acceptable use, access control, incident response, supplier security), and risk treatment plan with control owners assigned; Phase 3 (months 10–15) covering control implementation, internal audit program, and management review; Phase 4 (months 16–18) covering Stage 1 documentation review with certification body and Stage 2 on-site audit. Provide the Statement of Applicability template and the risk register column structure per ISO 27005.","tags":["compliance","iso-27001","isms","risk-management","certification"],"author":"AINOW","created":"2024-02-15T15:05:00Z","featured":false},

  {"id":"sec-63","title":"NIST CSF 2.0 Implementation for Mid-Size Enterprise","prompt":"You are a security program manager at a 1,200-person distribution company that has never formally assessed against a cybersecurity framework, following a ransomware near-miss that prompted the board to mandate a structured security improvement program. Design the NIST Cybersecurity Framework 2.0 implementation covering all six Functions: GOVERN (establish cybersecurity policy, assign roles and responsibilities per NIST CSF 2.0 GV.OC, GV.RM, GV.RR, GV.PO, GV.OV, GV.SC categories); IDENTIFY (asset inventory using Lansweeper for IT assets and a manual OT asset register, cybersecurity risk assessment using FAIR quantitative methodology, supply chain risk per GV.SC); PROTECT (implement CIS Controls v8 IG2 safeguards for your company size, focusing on MFA deployment, endpoint protection with CrowdStrike, and privileged access management); DETECT (deploy Microsoft Sentinel with basic detection rules for IG2 coverage); RESPOND (develop incident response plan aligned to NIST SP 800-61r2); RECOVER (test Veeam backup restoration quarterly, develop business continuity plan). Provide the NIST CSF 2.0 current-state and target-state profile table with prioritized gaps and the 18-month implementation timeline.","tags":["compliance","nist-csf","risk-management","cis-controls","framework"],"author":"AINOW","created":"2024-02-15T15:10:00Z","featured":false},

  {"id":"sec-64","title":"PCI DSS v4.0 Gap Assessment for E-Commerce Company","prompt":"You are a QSA (Qualified Security Assessor) conducting a PCI DSS v4.0 gap assessment for a 300-person e-commerce company that processes 2 million card transactions annually using Stripe for payment processing and storing some card data in their own database for recurring billing, qualifying as a Level 2 merchant. Conduct the gap assessment covering the 12 PCI DSS v4.0 requirements with emphasis on areas where v4.0 introduces new requirements versus v3.2.1: Requirement 3 (new: disk-level encryption alone is not sufficient for stored PAN — need field-level encryption or tokenization, new: automated technical controls to detect PAN outside approved locations), Requirement 6 (new: targeted risk analysis required for in-house developed software, new: all payment page scripts must be authorized and integrity must be verified — anti-skimming requirement 6.4.3), Requirement 8 (new: phishing-resistant MFA required for all CDE access by March 2025), Requirement 11 (new: internal vulnerability scanning every 3 months, new: change and tamper detection on payment pages). For each gap, specify the remediation effort (days), cost estimate, and the March 2025 deadline applicability. Provide the gap assessment table and the compensating control worksheet template.","tags":["compliance","pci-dss","e-commerce","gap-assessment","qsa"],"author":"AINOW","created":"2024-02-15T15:15:00Z","featured":false},

  {"id":"sec-65","title":"Quantitative Cyber Risk Assessment Using FAIR","prompt":"You are a cybersecurity risk manager at a 2,500-person insurance company preparing a quantitative risk assessment for the board and CFO, who have requested that security investments be justified in financial terms rather than qualitative High/Medium/Low ratings, using the FAIR (Factor Analysis of Information Risk) methodology. Conduct a FAIR analysis for the top three cyber risk scenarios: Scenario 1 — ransomware encrypting 80% of endpoints (Threat Event Frequency: 30% annual probability, Vulnerability: 40% probability given perimeter controls, Loss Magnitude using FAIR's six loss forms: primary response costs $800K, secondary loss including regulatory fines, business interruption at $2.2M, brand damage at $500K); Scenario 2 — customer PII breach via SQL injection in the customer portal (annual probability 15%, 2 million records affected, per-record breach cost $150 based on IBM 2023 report); Scenario 3 — BEC wire fraud (annual probability 25%, expected loss $250K per incident). For each scenario, produce the Monte Carlo simulation output showing the 10th, 50th, and 90th percentile loss exceedance values and the Return on Control Investment calculation for proposed security investments. Provide the FAIR model input table and the board-ready risk dashboard format.","tags":["compliance","risk-management","fair","quantitative-risk","board-reporting"],"author":"AINOW","created":"2024-02-15T15:20:00Z","featured":false},

  {"id":"sec-66","title":"Third-Party Vendor Risk Management Program","prompt":"You are a vendor risk management program lead at a 1,000-person financial services firm that relies on 450 third-party vendors including 12 critical SaaS platforms processing customer financial data, with no current formal vendor assessment process beyond contract legal review. Design a comprehensive Third-Party Risk Management program aligned to NIST SP 800-161r1 and the SEC cybersecurity rules for vendor oversight: vendor tiering model (Critical: vendors processing customer PII or financial data, High: vendors with network access to your environment, Medium: SaaS with employee data, Low: no data access); security assessment questionnaire per tier (Critical vendors: SIG Lite or CAIQ mapped to ISO 27001 Annex A controls, annual reassessment, SOC 2 Type II report review, penetration test report review, right-to-audit clause); continuous monitoring for Critical vendors using Bitsight or SecurityScorecard to track externally observable security posture changes; contract requirements checklist (mandatory breach notification within 72 hours, data processing agreement per GDPR Article 28, right to audit, data deletion on termination); and a vendor offboarding security checklist. Provide the Critical vendor questionnaire (25 key questions) and the vendor risk tiering decision tree.","tags":["compliance","vendor-risk","third-party","nist-800-161","financial-services"],"author":"AINOW","created":"2024-02-15T15:25:00Z","featured":false},

  {"id":"sec-67","title":"GDPR Data Protection Impact Assessment","prompt":"You are a Data Protection Officer at a 500-person European healthcare technology company launching a new AI-powered patient triage feature that processes special category health data from 200,000 patients across 5 EU member states, running on AWS eu-west-1 with a US-based AI model vendor (OpenAI API). Conduct a complete GDPR Data Protection Impact Assessment (DPIA) per Article 35 requirements: necessity and proportionality assessment (is the processing necessary for the stated purpose, are there less privacy-invasive alternatives to sending raw patient data to OpenAI, can pseudonymization reduce risk before API transmission); risks to the rights and freedoms of data subjects (automated decision-making risk per Article 22, discrimination risk from AI bias in triage scoring, data breach risk for special category health data); technical and organizational measures (data minimization — send only fields required for triage, not full patient record; pseudonymization before transmission to OpenAI; Standard Contractual Clauses and Transfer Impact Assessment for US data transfer; encryption in transit with TLS 1.3 and at rest with AES-256; access logging in CloudTrail); consultation with supervisory authority if residual risk remains high; and data subject rights fulfillment plan for this processing activity. Provide the DPIA document structure and the risk matrix template.","tags":["compliance","gdpr","dpia","healthcare","data-protection"],"author":"AINOW","created":"2024-02-15T15:30:00Z","featured":false},

  {"id":"sec-68","title":"Security Risk Register Design and Maintenance","prompt":"You are a GRC analyst at a 800-person logistics company building a formal security risk register for the first time, following the board's request for a quarterly cyber risk briefing, using ServiceNow GRC as the governance platform. Design the security risk register structure and governance process: risk identification methodology (annual workshops per business unit using NIST SP 800-30 risk assessment methodology, continuous input from Tenable vulnerability management, CrowdStrike threat intelligence feeds, and pen test findings); risk entry taxonomy (Risk ID, Risk Statement in the format 'Due to [threat] exploiting [vulnerability], the organization may experience [impact]', Asset Affected, Threat Actor, Threat Event, Vulnerability, Inherent Likelihood 1–5, Inherent Impact 1–5, Inherent Risk Score, Current Controls, Residual Likelihood, Residual Impact, Residual Risk Score, Risk Treatment: Accept/Mitigate/Transfer/Avoid, Treatment Action Plan, Risk Owner, Review Date); risk appetite statement aligned to board-approved thresholds (Accept residual risks rated Low or Medium below score 8, escalate High and Critical risks above score 15 to CISO and board); quarterly review process in ServiceNow with automated reminders to risk owners. Provide the risk register template with 5 example risk entries spanning the threat categories most relevant to logistics companies.","tags":["compliance","risk-management","grc","risk-register","servicenow"],"author":"AINOW","created":"2024-02-15T15:35:00Z","featured":false},

  {"id":"sec-69","title":"CMMC 2.0 Level 2 Compliance Roadmap for Defense Contractor","prompt":"You are the CISO of a 400-person defense contractor manufacturing precision components, holding a DoD contract with a DFARS clause requiring CMMC 2.0 Level 2 compliance assessment by the contract renewal date in 18 months. Your environment includes a CUI enclave on Windows Server 2022 with on-premise Active Directory, 120 cleared employees with CUI access, a manufacturing floor with Windows 7 legacy systems (isolated from CUI enclave), and a SPRS score currently self-assessed at 73 out of 110. Design the CMMC 2.0 Level 2 compliance roadmap covering all 110 practices across the 14 NIST SP 800-171 domains: prioritize the 68 practices currently assessed as Not Implemented focusing on highest-impact gaps (AC.L2-3.1.3 controlled access based on need-to-know for CUI, IA.L2-3.5.3 use of multi-factor authentication, SC.L2-3.13.3 CUI transmission encryption using FIPS 140-2 validated cryptography, SI.L2-3.14.7 identify unauthorized use of organizational systems using SIEM); System Security Plan development and maintenance; engagement of a C3PAO for the third-party assessment; and the POA&M management process for accepted risks during the assessment window. Provide the 18-month project plan and the SPRS score improvement roadmap.","tags":["compliance","cmmc","nist-800-171","defense-contractor","cui"],"author":"AINOW","created":"2024-02-15T15:40:00Z","featured":false},

  {"id":"sec-70","title":"Security Metrics and KPI Dashboard for Board Reporting","prompt":"You are a CISO at a 1,500-person publicly traded technology company preparing a quarterly board-level security metrics dashboard, following the SEC's cybersecurity disclosure rules requiring boards to demonstrate cybersecurity oversight. Design a security metrics framework covering five categories: Exposure Metrics (number of Critical CVEs unpatched beyond SLA by week, percentage of assets covered by vulnerability scanning, number of externally exposed services via Shodan API); Protection Metrics (MFA adoption rate across all users, percentage of endpoints with CrowdStrike Falcon deployed and active, percentage of backups tested successfully this quarter); Detection Metrics (Mean Time to Detect in hours trending over 4 quarters, percentage of alerts auto-resolved by SOAR versus requiring analyst intervention, number of threat hunting exercises completed with positive findings); Response Metrics (Mean Time to Contain in hours, percentage of incidents contained within SLA by severity tier, number of incidents escalating to the board-reportable threshold per SEC rules); and Program Maturity Metrics (NIST CSF current-state profile score trending, percentage of security awareness training completed, budget spend versus plan). For each metric, specify the data source (Tenable, CrowdStrike, Splunk, ServiceNow), the collection frequency, the target threshold, and the red/amber/green RAG status thresholds.","tags":["compliance","security-metrics","board-reporting","kpi","sec-disclosure"],"author":"AINOW","created":"2024-02-15T15:45:00Z","featured":false},

  {"id":"sec-71","title":"Splunk SIEM Detection Engineering for Insider Threat","prompt":"You are a detection engineer at a 2,000-person financial services firm using Splunk Enterprise Security with 500GB daily log ingest from CrowdStrike Falcon, Palo Alto firewall, Active Directory, and Microsoft 365 audit logs. Build a detection engineering program specifically targeting insider threat behaviors aligned to MITRE ATT&CK technique T1052 Exfiltration Over Physical Medium, T1567 Exfiltration to Cloud Storage, and T1048 Exfiltration over Alternative Protocol. For each of five detection use cases — large file uploads to personal Google Drive or Dropbox from corporate devices, mass file access in SharePoint within a 30-minute window, USB mass storage device insertion on endpoints, email forwarding rules created to external domains, and LDAP reconnaissance from a non-admin workstation — write the complete Splunk SPL query including data model acceleration, a risk-based alerting (RBA) risk score assignment, the false positive tuning logic, and the SOAR playbook trigger threshold. Include the Splunk ES notable event configuration and the analyst investigation guide for each use case.","tags":["security-operations","siem","splunk","insider-threat","detection-engineering"],"author":"AINOW","created":"2024-02-15T15:50:00Z","featured":true},

  {"id":"sec-72","title":"SOAR Playbook Design for Automated Phishing Response","prompt":"You are a SOC automation engineer at a 3,000-employee retail company using Palo Alto Cortex XSOAR, Microsoft 365 Defender, Proofpoint Email Security, and CrowdStrike Falcon, processing 200 phishing reports from employees daily with a 4-analyst SOC team currently spending 60% of time on email triage. Design a SOAR automation playbook in XSOAR for phishing email triage and response that reduces analyst time to under 2 minutes per alert: Trigger (employee submits email to phishing@company.com or Outlook report-phishing button); automated enrichment phase (extract all URLs, file hashes, sender domain, and IPs using XSOAR built-in regex extractors; query VirusTotal API for hash and URL reputation; query Proofpoint TAP for sender reputation; query CrowdStrike Falcon Intelligence for domain and IP threat context; check the sender domain against DMARC/SPF/DKIM results); automated verdict logic (if VirusTotal score above 5/72 engines OR Proofpoint TAP verdict is malicious → auto-quarantine and block; if benign indicators → auto-close with informational label); for malicious verdict: auto-quarantine via Microsoft Defender Threat Explorer API, create CrowdStrike custom IOC, notify the reporting employee, create ServiceNow ticket. Provide the XSOAR playbook task flow in pseudocode and the VirusTotal XSOAR integration command syntax.","tags":["security-operations","soar","xsoar","phishing","automation"],"author":"AINOW","created":"2024-02-15T15:55:00Z","featured":false},

  {"id":"sec-73","title":"SOC Alert Triage Model and Tier 1 Analyst Runbook","prompt":"You are a SOC manager at a 1,800-person healthcare organization running a 24x7 SOC with 8 Tier 1 analysts handling 400 alerts daily from Microsoft Sentinel, CrowdStrike Falcon, and Tenable.sc, with an average false positive rate of 85% and analyst burnout leading to 40% annual turnover. Design a structured alert triage model and Tier 1 analyst runbook that reduces false positive investigation time: alert classification matrix mapping each Sentinel detection rule to a triage priority (P1 Active Ransomware or Active Data Exfiltration: 15-minute response SLA; P2 Successful Unauthorized Login or Malware Execution: 1-hour SLA; P3 Brute Force or Policy Violation: 4-hour SLA; P4 Informational: next business day); Tier 1 runbook for the top 10 highest-volume alert types with step-by-step investigation procedures, specific Sentinel KQL queries to run for context, the pivot points to enrich (user identity history in Entra ID, asset criticality from CMDB, recent CrowdStrike detections on same host), and the escalation criteria to Tier 2; analyst decision tree for the most common verdict outcomes (false positive, true positive benign, true positive malicious); and SOAR automation of the enrichment steps to pre-populate analyst investigation context before the alert appears in the queue. Provide the runbook template for the Successful Login from Impossible Travel alert type.","tags":["security-operations","soc","alert-triage","microsoft-sentinel","runbook"],"author":"AINOW","created":"2024-02-15T16:00:00Z","featured":false},

  {"id":"sec-74","title":"Log Management Architecture for PCI DSS and HIPAA","prompt":"You are a security architect at a 700-person healthcare payments company subject to both PCI DSS v4.0 Requirement 10 and HIPAA Audit Controls standard, currently storing logs in individual server syslog files with no centralized logging, facing an audit in 3 months. Design the complete log management architecture: log source inventory and coverage requirements (PCI DSS Requirement 10.2.1 requires logging of all individual user access to cardholder data, all actions by root or administrator, all access to audit logs, invalid logical access attempts, use of identification and authentication mechanisms, initialization of audit logs, and creation/deletion of system-level objects; HIPAA requires audit controls with 6-year retention); centralized log pipeline using Cribl Stream to collect syslog from Linux/Windows systems, CloudTrail JSON from AWS, and Microsoft 365 Unified Audit Log via Cribl's Microsoft 365 source, normalizing to Common Information Model (CIM) before forwarding to Splunk; log retention architecture (hot storage in Splunk for 90 days for active investigation, warm storage in AWS S3 with Intelligent Tiering for 12 months for PCI DSS and 6 years for HIPAA, immutable storage using S3 Object Lock to prevent log tampering per PCI DSS 10.3.3); log integrity verification using SHA-256 hashing of daily log archives. Provide the Cribl Stream pipeline configuration for Windows Event Log normalization.","tags":["security-operations","log-management","splunk","pci-dss","hipaa"],"author":"AINOW","created":"2024-02-15T16:05:00Z","featured":false},

  {"id":"sec-75","title":"Vulnerability Management Program with Tenable and Jira","prompt":"You are a vulnerability management program lead at a 2,500-person enterprise with 8,000 assets across AWS, Azure, and on-premise data centers, using Tenable.sc for on-premise and Tenable.io for cloud scanning, with no current SLA for vulnerability remediation and a backlog of 45,000 open findings. Design a mature vulnerability management program: scanning coverage and frequency (authenticated credentialed scans weekly for Tier 1 critical servers, bi-weekly for Tier 2 infrastructure, monthly for Tier 3 workstations, continuous agent-based scanning for cloud instances using Tenable Nessus Agent); risk-based prioritization model combining CVSS v3.1 base score, EPSS score (probability of exploitation in the next 30 days), CISA KEV catalog membership, asset criticality from ServiceNow CMDB, and internet exposure flag — producing a Vulnerability Priority Rating (VPR) score; SLA definition (CISA KEV vulnerabilities: 24 hours for internet-facing, 72 hours for internal; CVSS Critical 9.0+ not on KEV: 30 days; CVSS High 7.0–8.9: 60 days; CVSS Medium: 90 days); Jira integration for automatic ticket creation with assignee from CMDB owner field; and a monthly executive dashboard showing SLA compliance rate trending. Provide the Tenable.io API call to export findings with EPSS scores and the Jira automation rule for auto-closing tickets when Tenable confirms patch.","tags":["security-operations","vulnerability-management","tenable","jira","epss"],"author":"AINOW","created":"2024-02-15T16:10:00Z","featured":false},

  {"id":"sec-76","title":"Threat Detection Rule Lifecycle Management","prompt":"You are a detection engineering team lead at a 1,500-person technology company running Microsoft Sentinel with 340 active detection rules, 60% of which have never been reviewed since creation, generating 250 alerts daily with a 78% false positive rate. Design a Detection Rule Lifecycle Management program: rule inventory and health scoring (for each rule: false positive rate over 90 days from Sentinel analytics, MITRE ATT&CK technique coverage, last tested date, data source dependency health, and a rule quality score 1–10); quarterly rule review cadence (retire rules with false positive rate above 95% and no true positives in 6 months, tune rules with FP rate 80–95% by adding exclusion conditions for known benign patterns, validate rules with FP rate below 20% against Atomic Red Team tests to confirm they fire on real attacker behavior); detection coverage gap analysis using ATT&CK Navigator to visualize which techniques in your threat model have no detection coverage; new rule development pipeline (threat intelligence input → detection hypothesis → Sigma rule authoring → MITRE mapping → Sentinel KQL implementation → unit test against synthetic log data → staged rollout to Sentinel Alert but not Incident for 2-week tuning period → full promotion to Incident creation); and metrics for detection program health (detection coverage percentage, mean time from threat intelligence to deployed detection rule). Provide the Sigma rule template and the KQL conversion pattern for Windows Event ID 4688 process creation detection.","tags":["security-operations","detection-engineering","microsoft-sentinel","sigma","mitre-attack"],"author":"AINOW","created":"2024-02-15T16:15:00Z","featured":false},

  {"id":"sec-77","title":"Security Operations Center Metrics and Maturity Model","prompt":"You are a SOC director at a 3,000-person financial services firm managing a 15-analyst in-house SOC supplemented by a managed detection and response (MDR) provider covering overnight hours, using Splunk as SIEM and ServiceNow for ticketing. Design a SOC maturity assessment and improvement roadmap using the SOC Capability Maturity Model framework: assess current maturity across five dimensions — People (analyst skills matrix, training investment per analyst, certification coverage of SANS GCIA or GCIH), Process (documented playbooks for top 20 alert types, change management for detection rules, escalation procedures), Technology (SIEM data coverage against log source inventory, SOAR automation rate, EDR deployment coverage), Threat Intelligence (CTI feed integration, threat intelligence consumption in detections, IOC management process), and Metrics (MTTD, MTTR, false positive rate, analyst utilization rate); baseline current state at maturity levels 1–5; define 12-month target state with specific capability gaps to close; prioritize investments (hire a detection engineer, deploy SOAR to automate top 5 playbooks, integrate Recorded Future CTI into Splunk ES, achieve GCIH certification for all Tier 2 analysts); and design the monthly SOC performance scorecard. Provide the SOC maturity assessment rubric for the Process dimension across all 5 maturity levels.","tags":["security-operations","soc","maturity-model","metrics","mdr"],"author":"AINOW","created":"2024-02-15T16:20:00Z","featured":false},

  {"id":"sec-78","title":"Deception Technology and Honeypot Deployment Strategy","prompt":"You are a security engineer at a 1,200-person manufacturing company that has deployed CrowdStrike Falcon for EDR and Splunk for SIEM but has no early warning capability for lateral movement once an attacker is inside the network, and your Mean Time to Detect is currently 47 days. Design a deception technology deployment strategy using Attivo Networks (now SentinelOne Singularity Ranger) or Canarytokens.org for low-cost deception: honeypot placement strategy (deploy 3 high-interaction Windows Server honeypots in each network segment — office, manufacturing OT DMZ, IT server VLAN — configured to appear as file servers with fake business data and fake privileged account credentials in memory); Canarytoken deployment locations (fake AWS access key in a deceptively-named file on a file share called credentials_backup.xlsx, fake database connection string in a config file on the development server, HTTP Canarytoken embedded in a document called M&A_Strategy_CONFIDENTIAL.docx placed on the CFO's desktop); alert integration with Splunk (any interaction with honeypots or token triggers creates a P1 alert in Splunk ES with automatic CrowdStrike host isolation of the interacting endpoint); and breadcrumb deployment (fake cached credentials in LSASS on standard workstations pointing to honeypot admin shares). Provide the Canarytoken alert webhook configuration and the Splunk alert rule for honeypot interaction.","tags":["security-operations","deception","honeypot","canarytoken","lateral-movement"],"author":"AINOW","created":"2024-02-15T16:25:00Z","featured":false},

  {"id":"sec-79","title":"Cloud-Native SIEM Migration from On-Premise Splunk","prompt":"You are a security architect at a 2,000-person technology company running Splunk Enterprise on-premise with $800K annual licensing and hardware costs, considering migrating to Microsoft Sentinel as a cloud-native SIEM to reduce costs and improve cloud coverage for your Azure-heavy environment. Design the Splunk to Sentinel migration plan: data source migration assessment (map current Splunk data sources to Sentinel data connectors — Microsoft 365 Defender via native connector, AWS CloudTrail via S3-based connector using Sentinel's AWS S3 data connector, on-premise Windows and Linux via Azure Monitor Agent replacing Splunk Universal Forwarder, Palo Alto firewall via CEF syslog to Azure Monitor); detection rule migration (export Splunk correlation rules as SPL, convert to Sentinel KQL using the Sigma converter tool and manual review, validate parity using Sentinel's entity mapping and MITRE ATT&CK framework alignment); SOAR migration from Splunk SOAR to Sentinel Logic Apps and Microsoft Sentinel Automation (map existing playbooks to Logic App workflows, identify which playbooks can be replaced by Sentinel automation rules for simple actions); 90-day parallel running period with both SIEMs active to validate detection parity before Splunk decommission; and total cost of ownership comparison. Provide the SPL to KQL conversion table for the 10 most common Splunk search patterns and the Sentinel workspace architecture for multi-tenant isolation.","tags":["security-operations","siem","microsoft-sentinel","splunk","cloud-migration"],"author":"AINOW","created":"2024-02-15T16:30:00Z","featured":false},

  {"id":"sec-80","title":"OT/ICS Security Monitoring with Dragos and Claroty","prompt":"You are a security architect at a 900-person chemical manufacturing company with 400 OT assets including Siemens S7 PLCs, Honeywell DCS systems, Historian servers, and engineering workstations running Windows 7, connected to an IT/OT DMZ via a Cisco industrial firewall. The plant has suffered two production disruptions in 18 months from IT-originating malware crossing into the OT network. Design an OT security monitoring and defense-in-depth program: passive network monitoring deployment using Claroty Continuous Threat Detection (CTD) with SPAN ports on the OT network switches to build an asset inventory of all OT devices, protocols (Modbus, DNP3, EtherNet/IP, OPC-UA), and communication baselines without actively scanning fragile PLC assets; threat detection use cases specific to ICS (unauthorized engineering workstation connection to PLC, abnormal Modbus function code usage indicating PLC reprogramming attempt, historian server accessing the internet, TRITON/TRISIS-style safety instrumented system enumeration using T1046 Network Service Discovery in ICS context); integration with Splunk SIEM in the IT network via the Claroty Syslog output with normalized CIM-compatible events; Purdue Model network segmentation remediation plan to properly isolate Level 0–2 OT from Level 3–4 IACS DMZ; and incident response procedures specific to OT systems referencing ICS-CERT advisories and NERC CIP-007. Provide the Claroty alert-to-Splunk integration architecture and the OT incident response decision tree.","tags":["security-operations","ot-security","ics","claroty","industrial-security"],"author":"AINOW","created":"2024-02-15T16:35:00Z","featured":false},

  {"id":"sec-81","title":"Firewall Rule Audit and Zero-Trust Segmentation Design","prompt":"You are a network security engineer at a 1,500-person healthcare organization with a Palo Alto Networks firewall estate of 12 firewalls, 2,400 firewall rules accumulated over 8 years with no formal review process, including an estimated 30% unused rules and 15 'any-any' rules that create unrestricted paths between sensitive segments. Conduct a firewall rule audit and redesign: use Palo Alto Panorama's Security Policy Optimizer and Traffic Log analysis to identify unused rules (no traffic hits in 90 days), shadowed rules (rules covered entirely by preceding rules), and overly permissive rules (destination 'any' or service 'any'); risk-rank all 'any-any' rules by the network segments they connect (rules permitting access from the guest WiFi to the clinical network are Critical; rules allowing server-to-server any-any within the same server VLAN are Medium); redesign the segmentation model to isolate the following zones: Clinical Systems (Epic EHR, medical devices), Administrative (general office traffic), DMZ (internet-facing web servers), Data Center (databases, domain controllers), and Medical Device IoT (infusion pumps, imaging); implement application-based rules using Palo Alto App-ID to replace port-based rules; and establish a quarterly rule review and recertification process using Tufin Orchestration Suite. Provide the Palo Alto Panorama Security Policy Optimizer workflow and the HIPAA-aligned segmentation rule matrix.","tags":["network-security","firewall","palo-alto","segmentation","hipaa"],"author":"AINOW","created":"2024-02-15T16:40:00Z","featured":true},

  {"id":"sec-82","title":"VPN to Zero Trust Network Access Migration","prompt":"You are a network security architect at a 3,000-person financial services company with 2,500 remote workers accessing corporate resources via Cisco AnyConnect VPN, experiencing a flat network model where VPN-connected users have broad access to internal subnets, following two incidents where compromised VPN credentials led to broad lateral movement. Design the migration from VPN to Zero Trust Network Access (ZTNA) using Zscaler Private Access: application discovery phase (use Zscaler App Connector to passively discover all applications accessed via VPN over 30 days, creating an application inventory with usage frequency, user groups, and required network protocols); ZPA application segment design (replace subnet-based VPN split tunneling with per-application access policies — Salesforce users in group get access only to Salesforce-related internal APIs, finance team gets access only to ERP server on TCP 443, no broad network access); Connector deployment in AWS and on-premise data centers (HA pair of Zscaler App Connectors in each datacenter, connectors make outbound connections to Zscaler cloud so no inbound firewall ports required); Okta integration for identity-aware access policy (access to financial applications requires device compliance check via CrowdStrike Zero Trust Assessment score above 80 plus MFA via Okta); and phased migration plan with 90-day parallel VPN/ZPA period. Provide the ZPA application segment configuration for a 3-tier web application.","tags":["network-security","vpn","ztna","zscaler","zero-trust"],"author":"AINOW","created":"2024-02-15T16:45:00Z","featured":false},

  {"id":"sec-83","title":"Network Intrusion Detection with Suricata and Zeek","prompt":"You are a network security engineer at a 600-person technology company with a 10Gbps internet edge connection, a DMZ hosting 15 public-facing web servers, and no network-based intrusion detection capability, following a web server compromise that went undetected for 3 weeks. Design a network intrusion detection and traffic analysis program using open-source tools: deploy Suricata 7.0 inline (IPS mode) on a dedicated server with AF_PACKET for 10Gbps capture, with the Emerging Threats Pro ruleset plus custom rules for your technology stack (Node.js SSRF patterns, Spring Boot actuator endpoint probing, Kubernetes API server unauthorized access); deploy Zeek (formerly Bro) for connection logging, HTTP request logging, DNS query logging, and TLS certificate logging — Zeek's conn.log, http.log, dns.log, and ssl.log forwarded to Splunk for correlation; write custom Zeek scripts to detect C2 beacon behavior (regular outbound connections to the same external IP with consistent byte counts and 60-second jitter intervals — technique T1071.001 Application Layer Protocol HTTP); integrate Suricata alerts into Splunk via the Eve JSON output and correlate with CrowdStrike endpoint detections for the same host; and a network baseline anomaly approach using Splunk Machine Learning Toolkit to detect deviations in bytes transferred per destination country. Provide the Suricata rule syntax for detecting Cobalt Strike HTTPS C2 profile patterns and the Zeek beacon detection script.","tags":["network-security","ids","suricata","zeek","splunk"],"author":"AINOW","created":"2024-02-15T16:50:00Z","featured":false},

  {"id":"sec-84","title":"DNS Security and Protective DNS Implementation","prompt":"You are a network security engineer at a 2,000-person enterprise with on-premise Windows DNS servers handling internal resolution and no filtering on external DNS queries, where a recent threat hunting exercise found evidence of DNS-based C2 (long subdomain queries to dynamically generated domains consistent with DNS tunneling via T1071.004). Design a comprehensive DNS security program: deploy Cisco Umbrella as a protective DNS resolver for all on-premise and remote users (configure Windows DNS servers to forward all external queries to Umbrella, enforce DNS-over-HTTPS with Umbrella for remote workers via the Umbrella roaming client, block malware, phishing, command-and-control, and newly registered domain categories); DNS tunneling detection using Umbrella's machine learning detection plus custom Splunk query analyzing dns.log for queries with entropy above 4.0 bits per character in the subdomain label (consistent with Base64-encoded data in DNS TXT or A queries); DNSSEC implementation for your authoritative public zones to prevent DNS spoofing; internal DNS security (disable DNS zone transfers except to authorized secondary DNS servers, enable DNS audit logging on Windows DNS to Windows Security event logs forwarded to Splunk, alert on DNS record modifications for your critical domain zones); and a response procedure for confirmed DNS tunneling including host isolation via CrowdStrike. Provide the Splunk SPL query for DNS tunneling detection using entropy analysis.","tags":["network-security","dns","cisco-umbrella","dns-tunneling","protective-dns"],"author":"AINOW","created":"2024-02-15T16:55:00Z","featured":false},

  {"id":"sec-85","title":"Network Access Control with 802.1X and ClearPass","prompt":"You are a network security engineer at a 1,800-person university hospital with 15,000 devices connecting to the network — staff laptops, student devices, 3,000 medical IoT devices, vendor laptops, and guest devices — all currently landing in a flat network with no device authentication, after a medical device was used as an entry point for a ransomware attack. Design a Network Access Control program using Aruba ClearPass Policy Manager with 802.1X for wired and wireless networks: device profiling using ClearPass Profiling to automatically identify and categorize device types (Windows domain workstation, Apple iPhone, Siemens Healthineers infusion pump, guest device) based on MAC OUI, DHCP fingerprint, HTTP user agent, and Nmap active profiling; network segmentation enforcement using VLAN assignment policies (domain-joined Windows devices with current CrowdStrike agent: VLAN 10 Corporate; medical devices matching IoT device profiles: VLAN 20 Medical IoT with restricted access only to clinical application servers; unmanaged personal devices after web portal registration: VLAN 30 BYOD with internet-only access; unknown devices: VLAN 40 quarantine with redirect to IT helpdesk); 802.1X supplicant configuration for Windows devices via Intune certificate-based authentication using device certificates from your internal PKI; and a guest portal for patient WiFi using ClearPass Guest. Provide the ClearPass role-mapping policy syntax for medical device classification.","tags":["network-security","nac","802-1x","aruba-clearpass","medical-iot"],"author":"AINOW","created":"2024-02-15T17:00:00Z","featured":false},

  {"id":"sec-86","title":"DDoS Protection Architecture for E-Commerce Platform","prompt":"You are a network and infrastructure security engineer at a 400-person e-commerce company running on AWS that processes Black Friday peak traffic of 50,000 concurrent users and has suffered two DDoS attacks in the past 18 months — a volumetric L3 UDP flood (180 Gbps) and an L7 HTTP slow-read attack against the checkout flow — each causing 4-hour outages costing $180,000 in lost revenue per hour. Design a comprehensive DDoS protection architecture: AWS Shield Advanced subscription (automatic L3/L4 DDoS detection and mitigation, Route 53 health-check-based failover, 24x7 access to AWS DDoS Response Team during attacks, cost protection for scaling during DDoS events); CloudFront CDN deployment for the product catalog and checkout page as L7 protection layer with AWS WAF custom rule groups (rate-based rule limiting POST /checkout to 100 requests per 5 minutes per IP, geo-blocking for countries with no customer base, CAPTCHA challenge for suspicious traffic patterns identified by AWS WAF Bot Control); AWS WAF Managed Rules (AWS Core Rule Set, SQL injection rule group, known bad inputs rule group) deployed on the Application Load Balancer; traffic absorption using AWS Auto Scaling Groups pre-warming configuration and DDoS playbook for the engineering team during attack; and runbook for L7 attack response (identify attack signature using CloudFront access logs, create targeted WAF rule within 15 minutes, escalate to AWS DDoS Response Team). Provide the AWS WAF rate-based rule JSON and the CloudFront distribution security headers configuration.","tags":["network-security","ddos","aws-shield","aws-waf","cloudfront"],"author":"AINOW","created":"2024-02-15T17:05:00Z","featured":false},

  {"id":"sec-87","title":"PKI and Certificate Lifecycle Management Program","prompt":"You are a security engineer at a 2,500-person enterprise that suffered a production outage when a TLS certificate on a critical payment processing server expired undetected, causing $300,000 in lost transactions over 6 hours. Your environment has an estimated 2,000 certificates across internal and public-facing systems including AWS ACM, on-premise Windows IIS servers, Kubernetes ingress controllers, and Palo Alto firewall decryption certificates. Design a comprehensive PKI and certificate lifecycle management program: certificate inventory and discovery using Venafi Trust Protection Platform or Keyfactor Command to discover all certificates across AWS ACM, Windows Certificate Store, Kubernetes secrets, and Palo Alto — including certificate owner, expiry date, algorithm (flag SHA-1 and RSA-1024 for immediate replacement), and issuing CA; automated renewal workflows (ACM certificates auto-renew if DNS validation records are maintained; internal PKI certificates renewed automatically 30 days before expiry via Venafi automation; Kubernetes cert-manager with Let's Encrypt ACME protocol for ingress certificates); expiry alerting (90-day, 30-day, 14-day, and 7-day email alerts to certificate owner and security team via Venafi policy); algorithm deprecation enforcement (no new certificates with RSA below 2048-bit or SHA-1 signature, mandatory migration of all certificates to ECDSA P-384 for high-sensitivity applications by year-end); and TLS protocol version enforcement (TLS 1.2 minimum, TLS 1.3 preferred, explicit block of TLS 1.0 and 1.1 on all load balancers). Provide the Venafi policy configuration for certificate expiry alerting and the cert-manager ClusterIssuer YAML for Let's Encrypt.","tags":["network-security","pki","certificates","tls","venafi"],"author":"AINOW","created":"2024-02-15T17:10:00Z","featured":false},

  {"id":"sec-88","title":"Wireless Network Security Assessment and Hardening","prompt":"You are a network security engineer at a 800-person professional services firm with 35 office locations, each with Cisco Meraki wireless infrastructure, a mix of corporate WPA2-Enterprise 802.1X SSID and a guest WPA2-PSK SSID, following a penetration test finding that the guest SSID password has not been changed in 3 years and a rogue access point was detected in one location. Design a comprehensive wireless network security program: WPA2-Enterprise hardening (enforce EAP-TLS certificate-based authentication instead of EAP-PEAP-MSCHAPv2 to eliminate credential harvesting via evil twin attacks, validate server certificate in supplicant configuration to prevent PEAP downgrade, configure Meraki RADIUS to require CrowdStrike device compliance before network access using Cisco ISE integration); guest network isolation (automate WPA2-PSK rotation to a random 16-character password monthly via Meraki API, ensure complete L2 and L3 isolation from corporate network with client-to-client blocking enabled, DNS filtering via Umbrella on the guest SSID); rogue AP detection (enable Meraki Air Marshal for continuous rogue AP detection and containment, alert to Splunk via Meraki webhook when rogue AP is detected or when deauthentication attacks are observed); and wireless penetration testing methodology for the annual assessment (evil twin attack simulation, KRACK vulnerability verification on legacy devices, 802.11 management frame analysis). Provide the Meraki Air Marshal alert webhook configuration and the EAP-TLS supplicant policy for Intune Windows devices.","tags":["network-security","wireless","802-1x","cisco-meraki","evil-twin"],"author":"AINOW","created":"2024-02-15T17:15:00Z","featured":false},

  {"id":"sec-89","title":"Email Security Gateway Hardening and Anti-Spoofing","prompt":"You are a messaging security engineer at a 1,500-person financial services firm using Proofpoint Email Protection as your email security gateway for Microsoft 365, having experienced a successful spearphishing attack against senior executives using a look-alike domain, and where DMARC is currently in p=none monitoring mode with no enforcement, allowing any spoofed email to reach inboxes. Design a comprehensive email security hardening program: DMARC enforcement migration from p=none to p=reject (audit current DMARC aggregate reports via dmarcian or Valimail to identify all legitimate email-sending services for your domain, ensure all legitimate senders have aligned SPF or DKIM, create sub-domain policies for all subdomains, move to p=quarantine for 30 days to validate no legitimate mail is blocked, then p=reject); DKIM configuration for all mail streams (Proofpoint for inbound-relayed mail, Microsoft 365 for direct sends, Salesforce for marketing, SendGrid for transactional); Proofpoint Targeted Attack Protection (TAP) configuration (URL rewriting for all URLs with real-time sandbox analysis, attachment sandboxing in Proofpoint TAP for Office documents and PDFs, VIP list for executive spearphishing protection with additional analysis); look-alike domain monitoring using Proofpoint DMARC's domain fraud protection or Recorded Future Brand Intelligence; and executive email warning banner policy for external emails. Provide the DMARC record syntax for p=quarantine with RUA and RUF reporting and the SPF record structure for a multi-vendor environment.","tags":["network-security","email-security","proofpoint","dmarc","anti-phishing"],"author":"AINOW","created":"2024-02-15T17:20:00Z","featured":false},

  {"id":"sec-90","title":"Micro-Segmentation Implementation for Data Center","prompt":"You are a network security architect at a 1,000-person healthcare organization with a VMware vSphere-based data center hosting 300 virtual machines in a flat internal network — once an attacker reaches any VM, they can communicate laterally with all 300 — housing the Epic EHR application stack, Active Directory, file servers, and development systems in the same uncontrolled broadcast domain. Design a micro-segmentation implementation using VMware NSX-T: workload discovery and grouping phase (use NSX-T Flow Monitoring for 30 days to baseline all east-west traffic between VMs, import VM attributes from vSphere tags into NSX-T security groups — Epic App Server, Epic Database Server, AD Domain Controller, File Server, Dev Workstation); policy design using the 5-tuple micro-segmentation model (Epic App Server group: allow inbound TCP 443 from load balancer, allow outbound TCP 1433 to Epic Database group only, deny all other traffic; Active Directory group: allow inbound TCP 389/636/88/445/3268 from all domain-joined VM groups, deny any inbound from Dev group; default deny-all inter-group policy with explicit allow rules logged in NSX-T firewall log forwarded to Splunk); zero-day containment workflow (if CrowdStrike detects active ransomware on a VM, automatically quarantine via NSX-T API call from XSOAR playbook to add VM to an isolated quarantine group with all traffic denied); and phased rollout approach (10 VMs in monitor mode, then enforce). Provide the NSX-T Distributed Firewall policy YAML and the XSOAR NSX-T quarantine playbook task.","tags":["network-security","micro-segmentation","vmware-nsx","data-center","east-west"],"author":"AINOW","created":"2024-02-15T17:25:00Z","featured":false},

  {"id":"sec-91","title":"Phishing Simulation Program Design with KnowBe4","prompt":"You are a security awareness program manager at a 2,500-person retail company where a baseline phishing simulation found a 34% click rate and 18% credential submission rate, following a real phishing attack that compromised 12 employee accounts. Design a comprehensive phishing simulation and awareness program using KnowBe4: simulation campaign strategy (monthly simulations for all 2,500 employees, rotating through 6 phishing templates per year covering spearphishing with CEO lure, credential harvesting mimicking Microsoft 365 login, smishing via mobile-themed lure, vishing scripts for help desk testing, QR code phishing, and invoice fraud BEC lure); difficulty progression (start with easier templates rating 3/10 difficulty for the first quarter, increase to 7/10 by quarter 4 as click rates improve, use smart groups to automatically assign harder templates to employees who passed previous simulations); training assignment automation (employees who click are automatically enrolled in KnowBe4's 'Just-in-Time' training module — a 10-minute interactive module specific to the phishing type they fell for); department-level reporting dashboard for managers; integration with Okta to automatically flag accounts of employees who submitted credentials in simulations as Risky in Entra ID for additional scrutiny; and a program success metric of below 5% click rate and below 1% credential submission rate within 12 months. Provide the KnowBe4 Smart Group filter criteria for escalating training and the phishing simulation template strategy per quarter.","tags":["security-awareness","phishing-simulation","knowbe4","training","human-risk"],"author":"AINOW","created":"2024-02-15T17:30:00Z","featured":true},

  {"id":"sec-92","title":"Security Champion Program for 50 Engineering Teams","prompt":"You are a product security manager at a 1,200-person technology company with 50 engineering squads shipping code daily, a 4-person AppSec team that cannot review every code change, and a penetration test finding 22 security vulnerabilities in production that had been present for 6+ months undetected. Design a Security Champion Program: champion selection criteria (1 champion per squad with interest in security, minimum 1 year tenure, no additional dedicated time required — security is embedded into existing role); onboarding curriculum for new champions (8-hour onboarding: OWASP Top 10 fundamentals, how to use Semgrep and Snyk in the IDE, how to run an OWASP Threat Dragon lightweight threat model, how to triage a Dependabot alert, how to report a security finding to the AppSec team via the security.txt disclosure process); ongoing enablement (monthly 1-hour champion meeting with AppSec team covering recent security incidents relevant to your tech stack, quarterly champion-led threat modeling workshop for their squad, access to a champion Slack channel for real-time AppSec advice, annual OWASP AppSec conference attendance budget of $2,500 per champion); recognition and incentive program (security bug bounty for internal findings — $200 gift card for High findings, $500 for Critical); and program KPIs (security findings per sprint caught by champions vs. found in pentest, champion retention rate, squad-level secure coding score from Semgrep trending). Provide the champion onboarding training agenda and the internal security bug reporting template.","tags":["security-awareness","security-champions","appsec","developer-security","program-management"],"author":"AINOW","created":"2024-02-15T17:35:00Z","featured":false},

  {"id":"sec-93","title":"Executive and Board Cybersecurity Education Program","prompt":"You are the CISO at a 3,000-person publicly traded company where the board of directors has requested cybersecurity education following the SEC's cybersecurity disclosure rules requiring board oversight expertise, and where the previous CISO-to-board briefing was a 60-slide technical deck that resulted in zero actionable decisions. Design a board and executive cybersecurity education program: annual board education session (90 minutes: opening with a live simulation of the company's public attack surface using Shodan showing real exposed assets — no jargon, just 'these are open doors to your company'; a tabletop exercise scenario involving a ransomware attack requiring board decisions on ransom payment, regulatory disclosure timing, and public communications; Q&A on personal cyber hygiene for executives who handle M&A information); executive CISO briefing cadence (quarterly 20-minute board committee briefing using only 5 metrics: current cyber risk rating vs. peer benchmark, number of material incidents this quarter, top threat facing the industry per current CTI, percentage of critical systems meeting security baseline, and one investment decision required from the board); personal security briefing for C-suite (30-minute 1:1 session with CEO/CFO/General Counsel covering personal device security, executive spearphishing awareness, travel security for international trips, and the insider threat risk from their own access). Provide the 5-metric board dashboard template and the tabletop exercise scenario script for a ransomware board decision session.","tags":["security-awareness","board-education","executive-security","governance","ciso"],"author":"AINOW","created":"2024-02-15T17:40:00Z","featured":false},

  {"id":"sec-94","title":"Role-Based Security Training Curriculum Design","prompt":"You are a security training program manager at a 4,000-person healthcare organization subject to HIPAA Security Rule training requirements (45 CFR 164.308(a)(5)) and HITRUST CSF control 07.d, where the current training program is a single 30-minute annual HIPAA awareness module with 100% completion on paper but zero behavioral change as evidenced by 14 security incidents caused by employee error in the past year. Design a role-based security training curriculum with six role-specific tracks: Clinical Staff track (15-minute modules on PHI handling in Epic, recognizing phishing targeting healthcare workers, medical device security practices, and proper disposal of paper PHI — completed during onboarding and annually thereafter); IT and Engineering track (2-hour annual training on OWASP Top 10 relevant to your tech stack, secure coding practices in Python and JavaScript, cloud security in AWS, and incident reporting procedures); Finance and Accounts Payable track (45-minute training on BEC and wire fraud recognition, payment verification procedures, and CEO impersonation fraud — with a simulated fraudulent wire transfer exercise); HR and Recruiting track (30-minute training on social engineering via fake job candidate attacks, data handling of applicant PII, and background check policy); Executives track (30-minute annual training on executive spearphishing and vishing, secure travel practices, and personal device hygiene); and Vendor and Third-Party track (15-minute training required before network access provisioned). Provide the clinical staff training module outline and the HIPAA training completion tracking requirements for OCR audit evidence.","tags":["security-awareness","role-based-training","hipaa","healthcare","training-program"],"author":"AINOW","created":"2024-02-15T17:45:00Z","featured":false},

  {"id":"sec-95","title":"Security Culture Assessment and Behavioral Change Program","prompt":"You are a security culture program lead at a 1,800-person financial services company where qualitative surveys show employees view security as 'IT's problem', the CISO receives minimal engagement on security communications, and security policies have a documented 40% non-compliance rate for clean desk and USB usage. Design a scientific approach to security culture change using behavioral science principles: culture baseline assessment using the CybSafe Human Risk Management platform or a validated security culture survey (Likert-scale questions across 7 dimensions: Knowledge, Attitude, Behavior, Compliance, Norms, Communication, Responsibility) deployed to a stratified random sample of 600 employees across all business units and seniority levels; root cause analysis of non-compliant behaviors using the COM-B model (Capability, Opportunity, Motivation-Behavior) to distinguish whether non-compliance stems from lack of knowledge, lack of physical opportunity to comply, or lack of motivation; targeted interventions per root cause (capability gap → micro-learning content delivered via Microsoft Viva Learning; opportunity gap → redesign the physical environment with clear desk reminder stickers and USB port blockers; motivation gap → positive reinforcement program with department leaderboards and monthly recognition); 12-month re-assessment to measure behavioral change against baseline; and board reporting on Human Risk Score trending. Provide the COM-B analysis template for the clean desk policy non-compliance problem and the survey instrument for the Norms dimension.","tags":["security-awareness","security-culture","behavioral-science","human-risk","com-b"],"author":"AINOW","created":"2024-02-15T17:50:00Z","featured":false},

  {"id":"sec-96","title":"Vishing and Social Engineering Defense Training","prompt":"You are a security awareness manager at a 900-person insurance company where the help desk was socially engineered three times in 12 months by attackers posing as new employees or executives requesting password resets, MFA bypass, and VPN credential provisioning — two of which led to account compromises. Design a comprehensive vishing and social engineering defense training program: help desk-specific training (2-hour live workshop for all 25 help desk staff covering the psychology of social engineering — authority, urgency, and familiarity as manipulation levers — with 6 realistic recorded vishing call examples including a fake CEO call and a fake IT vendor call, followed by role-play practice with a colleague playing the attacker); strict identity verification protocol implementation (all password reset requests require the employee to initiate the request through the self-service portal or with their manager's cosignature; phone-based requests require callback to the verified number in the HR system — never the number provided by the caller; 'urgent' requests from executives increase the verification level, not decrease it; written procedure card posted at every help desk workstation); live vishing simulation exercise (hired social engineering firm conducts 20 authorized vishing calls to help desk staff over 1 week; staff who comply with an unauthorized request without proper verification are enrolled in targeted coaching, not punished); and monthly help desk security bulletin covering recent vishing techniques. Provide the identity verification protocol flowchart and the 6 vishing scenario scripts used in the training workshop.","tags":["security-awareness","vishing","social-engineering","help-desk","identity-verification"],"author":"AINOW","created":"2024-02-15T17:55:00Z","featured":false},

  {"id":"sec-97","title":"New Employee Security Onboarding Program","prompt":"You are a security education manager at a 2,000-person technology company that onboards 400 new employees annually, where a post-incident analysis of 8 security incidents over 18 months found that 6 were caused by employees who had been with the company less than 90 days and had received only a 45-minute generic security video at orientation. Design a comprehensive new employee security onboarding program structured over 90 days: Day 1 in-person security briefing (30 minutes covering the top 3 security behaviors expected — how to recognize and report phishing, never sharing credentials or bypassing MFA, reporting lost devices within 1 hour — framed around real examples of the company being targeted, not generic examples); Week 1 online modules (3 x 20-minute modules: Data Classification and Handling aligned to your 4-tier classification policy, Acceptable Use Policy with specific do's and don'ts for cloud storage and personal device use, Incident Reporting procedure with the specific email and phone number to use); Days 30–60 role-specific training (engineers complete the secure coding module for their technology stack via Secure Code Warrior; finance staff complete the BEC and wire fraud module; all staff complete a phishing simulation with immediate just-in-time feedback if they click); Day 90 knowledge assessment (20-question quiz with 80% pass mark required to maintain system access, automatic remediation training for failed areas); and manager checklist for security onboarding verification. Provide the Day 1 security briefing script and the 20-question Day 90 assessment question bank.","tags":["security-awareness","onboarding","new-employee","training","security-culture"],"author":"AINOW","created":"2024-02-15T18:00:00Z","featured":false},

  {"id":"sec-98","title":"Security Awareness Metrics and Program ROI Measurement","prompt":"You are a security awareness program manager at a 5,000-person enterprise that spends $450,000 annually on KnowBe4 licenses, content development, and program management, and needs to justify the budget to the CFO using quantitative ROI data rather than completion rates. Design a security awareness program measurement framework that demonstrates financial return: leading indicators (phishing simulation click rate trending monthly by department — target below 5%; credential submission rate — target below 1%; training completion rate within SLA — target 95% within 14 days of assignment; reporting rate of real phishing emails via the Phish Alert Button — increasing reporting is a positive behavioral indicator); lagging indicators (number of security incidents attributed to human error per quarter trending year-over-year; number of successful account takeovers via phishing per quarter; average cost per human-error-caused incident using ServiceNow incident cost data); ROI calculation methodology (cost avoided = incidents prevented × average incident cost; if baseline rate was 8 human-error incidents per year at $45,000 average cost = $360,000 in annual risk exposure; program reduces to 3 incidents = $225,000 cost avoided against $450,000 investment — show full calculation with sensitivity analysis); and a Balanced Scorecard for the security awareness program. Provide the ROI calculation template and the KnowBe4 reporting configuration for extracting the department-level click rate trend data.","tags":["security-awareness","metrics","roi","program-management","knowbe4"],"author":"AINOW","created":"2024-02-15T18:05:00Z","featured":false},

  {"id":"sec-99","title":"Travel Security Briefing for High-Risk Country Visits","prompt":"You are a corporate security manager at a 1,500-person technology company whose employees travel to 45 countries annually, including high cyber-risk destinations such as China, Russia, UAE, and India, where corporate espionage via compromised hotel WiFi, device seizure at borders, and social engineering of traveling executives represents a documented threat from nation-state actors. Design a comprehensive travel security briefing and operational program for employees traveling to high-risk countries: pre-travel requirements (loaner 'travel device' policy — clean laptop with only required applications, no persistent VPN credentials or sensitive files stored locally, mobile phone with eSIM for local data avoiding SIM theft, YubiKey for MFA since SMS OTP is unreliable and potentially interceptable internationally); country-specific threat briefing (for China travel: assume hotel room devices and WiFi are monitored, Customs may inspect and clone devices at border — use encrypted external drive with only trip-specific files, never connect to untrusted USB chargers — juice jacking risk via O.MG cable); operational security during travel (use Zscaler Private Access for all corporate access rather than hotel VPN, use Signal for sensitive communications, enable full-disk encryption with pre-boot PIN before travel, enable remote wipe via Intune before departure); device inspection protocol on return (submit travel devices to IT security for forensic review if visiting a Tier 1 risk country, review for unauthorized certificates or MDM profiles installed); and executive travel security for individuals with access to M&A information. Provide the pre-travel device preparation checklist and the country risk tier classification criteria.","tags":["security-awareness","travel-security","device-security","nation-state","operational-security"],"author":"AINOW","created":"2024-02-15T18:10:00Z","featured":false},

  {"id":"sec-100","title":"Security Awareness Program Annual Planning and Budget Justification","prompt":"You are the security awareness program manager at a 3,500-person healthcare company preparing the annual security awareness program plan and budget request for the coming fiscal year, presenting to the CISO and CFO. The current program consists of annual HIPAA training with 94% completion rate but a 28% phishing simulation click rate and 3 BEC incidents costing a combined $180,000 in the past year. Develop a comprehensive annual program plan and budget justification: current state assessment (completion rate metric is a vanity metric — the real measure is behavioral change evidenced by 28% click rate and 3 BEC incidents, benchmark against healthcare sector average of 15% click rate from KnowBe4 2024 Phishing By Industry report); proposed program expansion (upgrade from annual training to monthly micro-learning modules delivered via KnowBe4 ModStore — 5-minute mobile-friendly modules; monthly phishing simulations with difficulty progression; department-specific training for finance, clinical, and IT roles; quarterly help desk vishing tests; executive security briefing series); budget request breakdown ($180,000: KnowBe4 Diamond license for 3,500 users at $35/user $122,500; content development for 6 custom healthcare-specific modules at $5,000 each $30,000; external social engineering assessment $27,500); ROI justification (3 BEC incidents at $60,000 average cost equals $180,000 annual risk; industry data shows 60% reduction in incidents after mature awareness programs equals $108,000 cost avoided; program pays for itself in Year 1); and 12-month implementation timeline with quarterly milestones. Provide the budget justification one-pager for the CFO and the 12-month program calendar.","tags":["security-awareness","program-planning","budget","roi","healthcare"],"author":"AINOW","created":"2024-02-15T18:15:00Z","featured":false}

];
  __exports.cybersecurityPrompts = cybersecurityPrompts;
})();
